//! Row identities, row images, the delta operations shipped to clients,
//! and the shared frame those deltas are computed against.
//!
//! Two layers live here. The **wire vocabulary** — [`DataFrameKey`] (which
//! row), [`DataFrameRow`] (its image), [`DataFrameOperation`] (what
//! happened to it) — is what crosses the boundary: clients only ever
//! receive operations, never a frame. The **shared frame** —
//! [`TableFrame`] of [`SharedRow`]s — is the engine's materialization: one
//! frame per table, each row stored once and tagged with every
//! subscription holding it; it never crosses the boundary.
//!
//! Inside the engine the operation stream's ordering contract is per key:
//! operations on the same key are applied in stream order — a row changing
//! in place is `Delete(old)` immediately followed by `Add(new)`, and a row
//! admitted and then evicted within one step ships its `Add` before its
//! `Delete`. Operations on different rows commute. What leaves the engine
//! is the per-row fold of that stream (see `ivm::Delta`), where an
//! in-place change has collapsed to the one `Add` a receiver applies as
//! insert-or-replace.

use std::collections::HashMap;
use std::fmt;
use std::hash::{Hash, Hasher};
use std::sync::Arc;

use super::ids::{IdMap, IdSet};
use super::query::SubId;
use super::row::RowData;
use super::row::RowSchema;
use super::schema::ColumnName;
use super::value::{Value, unordered_pairs_hash};

/// The identity of a row: its primary-key values — deliberately nothing
/// else.
///
/// The table is encoded by location (the engine keys its shared frames by
/// table name), which queries hold the row is fan-out metadata kept beside
/// the row (the engine's per-row subscriber tags), and which subscription
/// an operation addresses rides in the envelope around the operation.
/// Putting any of those into the key would either repeat them per row and
/// per wire operation, or — for a query id — split one shared row into
/// many identities and undo the sharing.
///
/// The values are immutable once built and shared: a clone is a reference
/// count, so a key travels to every subscription and client of a row
/// without being copied. The order-independent hash of the map (a
/// `HashMap` field has order-independent equality, so the hash must be
/// too — see `unordered_map_hash` in `model::value`) is computed once at
/// construction and carried, so hashing a key is hashing one integer.
#[derive(Clone)]
pub struct DataFrameKey {
    pub pkey_value: Arc<RowData>,
    hash: u64,
}

impl DataFrameKey {
    /// A key laid out on `schema` (a table's key columns, shared by every
    /// row decoded from it) with `values` in that order.
    pub fn with_schema(schema: Arc<RowSchema>, values: Vec<Value>) -> Self {
        let pkey_value = RowData::with_schema(schema, values);
        DataFrameKey {
            hash: unordered_pairs_hash(pkey_value.iter()),
            pkey_value: Arc::new(pkey_value),
        }
    }
}

impl PartialEq for DataFrameKey {
    /// Equal primary-key maps; the carried hash rejects most unequal
    /// pairs without touching the maps.
    fn eq(&self, other: &Self) -> bool {
        Arc::ptr_eq(&self.pkey_value, &other.pkey_value)
            || (self.hash == other.hash && self.pkey_value == other.pkey_value)
    }
}

impl Eq for DataFrameKey {}

impl Hash for DataFrameKey {
    /// The hash computed at construction.
    fn hash<H: Hasher>(&self, state: &mut H) {
        state.write_u64(self.hash);
    }
}

impl fmt::Debug for DataFrameKey {
    /// The primary-key map alone.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("DataFrameKey")
            .field("pkey_value", &*self.pkey_value)
            .finish()
    }
}

impl From<HashMap<ColumnName, Value>> for DataFrameKey {
    /// A key over a finished primary-key map (a layout of its own).
    fn from(pkey_value: HashMap<ColumnName, Value>) -> Self {
        let pkey_value = RowData::from(pkey_value);
        DataFrameKey {
            hash: unordered_pairs_hash(pkey_value.iter()),
            pkey_value: Arc::new(pkey_value),
        }
    }
}

/// One full row image. v1 has no column projection
/// (`SingleTableReadQuery` selects whole rows), so this is the whole row.
///
/// The image is immutable once built and shared: a clone is a reference
/// count. A row decoded from the feed or from storage is allocated once
/// and that one allocation is what the frame holds and what every
/// subscription, client and poke of the row refers to.
#[derive(Clone, PartialEq)]
pub struct DataFrameRow {
    pub data: Arc<RowData>,
}

impl DataFrameRow {
    /// Builds a row image from `(column, value)` pairs.
    pub fn new(pairs: impl IntoIterator<Item = (impl Into<ColumnName>, Value)>) -> Self {
        DataFrameRow::from(
            pairs
                .into_iter()
                .map(|(column, value)| (column.into(), value))
                .collect::<HashMap<_, _>>(),
        )
    }
}

impl From<HashMap<ColumnName, Value>> for DataFrameRow {
    /// An image over a finished column map (a schema of its own).
    fn from(data: HashMap<ColumnName, Value>) -> Self {
        DataFrameRow {
            data: Arc::new(RowData::from(data)),
        }
    }
}

impl From<RowData> for DataFrameRow {
    /// An image over a row already laid out (a decoder's, on the table's
    /// shared schema).
    fn from(data: RowData) -> Self {
        DataFrameRow {
            data: Arc::new(data),
        }
    }
}

impl fmt::Debug for DataFrameRow {
    /// The column map alone.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("DataFrameRow")
            .field("data", &*self.data)
            .finish()
    }
}

/// The unit of an incremental update — self-contained, with no pre-image
/// side channel:
///
/// - `Add(key, row)`: the row enters the result set with this image; a
///   receiver applies it as insert-or-replace.
/// - `Delete(key, row)`: the row leaves, and it carries the removed image —
///   a bare key would say nothing about the values that just vanished,
///   which downstream consumers (join maintenance, clients) need.
#[derive(Debug, Clone, PartialEq)]
pub enum DataFrameOperation {
    Delete(DataFrameKey, DataFrameRow),
    Add(DataFrameKey, DataFrameRow),
}

/// The engine's compact id for one row of one table's frame: handed out
/// once when the row first enters the frame and retired, never reused,
/// when its last holder leaves. Per table, so never globally unique.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct RowId(pub u64);

/// One row of a shared frame: its identity, its current image, and the
/// subscriptions holding it — the "which query sets is this row subscribed
/// to" index that membership routing reads. The image is the current one
/// for every holder: the runtime brings every read up to the engine's
/// position before landing it, so no holder ever sees a different image.
pub struct SharedRow {
    pub key: DataFrameKey,
    pub data: DataFrameRow,
    pub subscribers: Holders,
}

/// The subscriptions holding one row, as a sorted vector: most rows have
/// one to a few holders, and a set's node per row cost more than the
/// row's own key.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Holders(Vec<SubId>);

impl Holders {
    /// No holders.
    pub fn new() -> Self {
        Holders(Vec::new())
    }

    /// Add `sub`; whether it was new.
    pub fn insert(&mut self, sub: SubId) -> bool {
        match self.0.binary_search(&sub) {
            Ok(_) => false,
            Err(at) => {
                self.0.insert(at, sub);
                true
            }
        }
    }

    /// Remove `sub`; whether it was there.
    pub fn remove(&mut self, sub: &SubId) -> bool {
        match self.0.binary_search(sub) {
            Ok(at) => {
                self.0.remove(at);
                true
            }
            Err(_) => false,
        }
    }

    /// Whether `sub` holds the row.
    pub fn contains(&self, sub: &SubId) -> bool {
        self.0.binary_search(sub).is_ok()
    }

    /// Whether nobody holds the row.
    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    /// How many hold the row.
    pub fn len(&self) -> usize {
        self.0.len()
    }

    /// The holders, ascending.
    pub fn iter(&self) -> std::slice::Iter<'_, SubId> {
        self.0.iter()
    }
}

impl SharedRow {
    /// Whether `sub` holds this row.
    pub fn held_by(&self, sub: SubId) -> bool {
        self.subscribers.contains(&sub)
    }
}

/// The one shared frame of a table: row identity → row id → shared row.
///
/// Engine state, not wire vocabulary — a subscription's view of it is the
/// rows tagged with its id, and reaches the client only as operations.
/// Every (subscription, row) pair is stored as two small integers (a tag
/// on the row, an entry in the subscription's held index), never as a
/// copy of the key or the subscription's name. Columns the engine asks
/// for ([`TableFrame::index_column`], the join columns) are indexed by
/// value, so the rows carrying one join value are found without a scan;
/// the indexes follow every row in, every image change and every row out.
#[derive(Default)]
pub struct TableFrame {
    ids: IdMap<DataFrameKey, RowId>,
    rows: IdMap<RowId, SharedRow>,
    indexes: HashMap<ColumnName, HashMap<Value, IdSet<RowId>>>,
    next_id: u64,
}

impl TableFrame {
    /// The row id of `key`, if the frame holds the row.
    pub fn id_of(&self, key: &DataFrameKey) -> Option<RowId> {
        self.ids.get(key).copied()
    }

    /// The shared row of `key`.
    pub fn get(&self, key: &DataFrameKey) -> Option<&SharedRow> {
        self.rows.get(self.ids.get(key)?)
    }

    /// The shared row under `id`.
    pub fn row(&self, id: RowId) -> Option<&SharedRow> {
        self.rows.get(&id)
    }

    /// Every row the frame holds, with its id, in no particular order.
    pub fn rows(&self) -> impl Iterator<Item = (RowId, &SharedRow)> {
        self.rows.iter().map(|(id, row)| (*id, row))
    }

    /// The shared row under `id`, mutably, for its subscriber tags; an
    /// image changes through [`TableFrame::replace_image`], which keeps
    /// the value indexes in step.
    pub fn row_mut(&mut self, id: RowId) -> Option<&mut SharedRow> {
        self.rows.get_mut(&id)
    }

    /// The row for `key`, materialized with `data` and no holders if the
    /// frame did not hold it yet; returns its id and the row.
    pub fn entry(
        &mut self,
        key: &DataFrameKey,
        data: impl FnOnce() -> DataFrameRow,
    ) -> (RowId, &mut SharedRow) {
        let id = match self.ids.get(key) {
            Some(id) => *id,
            None => {
                let id = RowId(self.next_id);
                self.next_id += 1;
                let data = data();
                self.ids.insert(key.clone(), id);
                self.index_row(id, &data);
                self.rows.insert(
                    id,
                    SharedRow {
                        key: key.clone(),
                        data,
                        subscribers: Holders::new(),
                    },
                );
                id
            }
        };
        (id, self.rows.get_mut(&id).expect("inserted or found above"))
    }

    /// Give the row under `id` the image `data`, moving it between value
    /// buckets where an indexed column changed; the same image (the same
    /// allocation) changes nothing. Reports whether the row exists.
    pub fn replace_image(&mut self, id: RowId, data: DataFrameRow) -> bool {
        let Some(row) = self.rows.get(&id) else {
            return false;
        };
        if Arc::ptr_eq(&row.data.data, &data.data) {
            return true;
        }
        let old = row.data.clone();
        self.unindex_row(id, &old);
        self.index_row(id, &data);
        if let Some(row) = self.rows.get_mut(&id) {
            row.data = data;
        }
        true
    }

    /// Drop the row under `id` if no subscription holds it; reports
    /// whether it was dropped. The id is retired.
    pub fn drop_if_unheld(&mut self, id: RowId) -> bool {
        self.take_if_unheld(id).is_some()
    }

    /// `sub` lets go of the row under `id`: untag it, and if no
    /// subscription holds it any more take it out (the id retired) and
    /// hand it back, so a caller releasing many rows can free them off
    /// the engine's thread. One lookup per row.
    pub fn release(&mut self, id: RowId, sub: SubId) -> Option<SharedRow> {
        let row = self.rows.get_mut(&id)?;
        row.subscribers.remove(&sub);
        if !row.subscribers.is_empty() {
            return None;
        }
        let row = self.rows.remove(&id)?;
        self.ids.remove(&row.key);
        self.unindex_row(id, &row.data);
        Some(row)
    }

    /// [`TableFrame::drop_if_unheld`], handing the row out instead of
    /// freeing it, so a caller releasing many rows can free them off the
    /// engine's thread. The id is retired either way.
    pub fn take_if_unheld(&mut self, id: RowId) -> Option<SharedRow> {
        let unheld = self
            .rows
            .get(&id)
            .is_some_and(|row| row.subscribers.is_empty());
        if !unheld {
            return None;
        }
        let row = self.rows.remove(&id)?;
        self.ids.remove(&row.key);
        self.unindex_row(id, &row.data);
        Some(row)
    }

    /// Index `column` by value from now on (and over the rows already
    /// held); asking again for an indexed column changes nothing.
    pub fn index_column(&mut self, column: &ColumnName) {
        if self.indexes.contains_key(column) {
            return;
        }
        let mut by_value: HashMap<Value, IdSet<RowId>> = HashMap::new();
        for (id, row) in &self.rows {
            if let Some(value) = row.data.data.get(column) {
                by_value.entry(value.clone()).or_default().insert(*id);
            }
        }
        self.indexes.insert(column.clone(), by_value);
    }

    /// The ids of the rows whose `column` is `value`, from the column's
    /// index; `None` when the column is not indexed (the caller scans).
    pub fn rows_with(&self, column: &str, value: &Value) -> Option<Vec<RowId>> {
        let by_value = self.indexes.get(column)?;
        Some(
            by_value
                .get(value)
                .map(|ids| ids.iter().copied().collect())
                .unwrap_or_default(),
        )
    }

    /// File `id` under `data`'s value in every indexed column.
    fn index_row(&mut self, id: RowId, data: &DataFrameRow) {
        for (column, by_value) in self.indexes.iter_mut() {
            if let Some(value) = data.data.get(column) {
                by_value.entry(value.clone()).or_default().insert(id);
            }
        }
    }

    /// Unfile `id` from `data`'s value in every indexed column.
    fn unindex_row(&mut self, id: RowId, data: &DataFrameRow) {
        for (column, by_value) in self.indexes.iter_mut() {
            let Some(value) = data.data.get(column) else {
                continue;
            };
            if let Some(ids) = by_value.get_mut(value) {
                ids.remove(&id);
                if ids.is_empty() {
                    by_value.remove(value);
                }
            }
        }
    }

    /// Whether the frame holds no rows.
    pub fn is_empty(&self) -> bool {
        self.rows.is_empty()
    }

    /// How many rows the frame holds.
    pub fn len(&self) -> usize {
        self.rows.len()
    }
}

impl DataFrameKey {
    /// Builds a row identity from `(primary-key column, value)` pairs.
    pub fn new(pkey_value: impl IntoIterator<Item = (impl Into<ColumnName>, Value)>) -> Self {
        DataFrameKey::from(
            pkey_value
                .into_iter()
                .map(|(column, value)| (column.into(), value))
                .collect::<HashMap<_, _>>(),
        )
    }
}

impl DataFrameOperation {
    /// The identity of the row this operation touches.
    pub fn key(&self) -> &DataFrameKey {
        match self {
            DataFrameOperation::Add(key, _) => key,
            DataFrameOperation::Delete(key, _) => key,
        }
    }

    /// The row image this operation carries — the new image for an `Add`,
    /// the removed image for a `Delete`.
    pub fn row(&self) -> &DataFrameRow {
        match self {
            DataFrameOperation::Add(_, row) => row,
            DataFrameOperation::Delete(_, row) => row,
        }
    }
}

//! A row image as the engine holds it: the table's column names once,
//! shared by every row decoded from that table, and the values in that
//! order. A row used to be a hash map per row (its own buckets, its own
//! copy of every column name), which cost about ten times the data it
//! carried; here a row is one allocation of values, and a column lookup
//! is one small map probe on the shared schema. The API is the subset of
//! a map's the engine uses, so a row still reads as a map.

use std::collections::HashMap;
use std::fmt;
use std::ops::Index;
use std::sync::Arc;

use bytes::Bytes;
use once_cell::race::OnceBox;

use super::ids::IdMap;
use super::schema::ColumnName;
use super::value::Value;

/// The columns of a table's rows, in the order their values are stored,
/// and the position of each name (under a fast hash: a column name is a
/// catalog string, looked up once per condition per row); built once per
/// table and shared.
#[derive(Debug)]
pub struct RowSchema {
    names: Box<[ColumnName]>,
    positions: IdMap<ColumnName, u16>,
}

impl RowSchema {
    /// A schema over `names` in that order (a name that repeats keeps
    /// its first position).
    pub fn new(names: impl IntoIterator<Item = ColumnName>) -> Arc<Self> {
        let names: Box<[ColumnName]> = names.into_iter().collect();
        let mut positions = IdMap::with_capacity_and_hasher(names.len(), Default::default());
        for (index, name) in names.iter().enumerate() {
            positions.entry(name.clone()).or_insert(index as u16);
        }
        Arc::new(RowSchema { names, positions })
    }

    /// The position of `column`, if the schema has it.
    pub fn position(&self, column: &str) -> Option<usize> {
        self.positions.get(column).map(|index| *index as usize)
    }

    /// The column names in storage order.
    pub fn names(&self) -> &[ColumnName] {
        &self.names
    }

    /// How many columns.
    pub fn len(&self) -> usize {
        self.names.len()
    }

    /// Whether the schema has no columns.
    pub fn is_empty(&self) -> bool {
        self.names.is_empty()
    }
}

/// One row's values under a shared schema.
#[derive(Clone)]
pub struct RowData {
    schema: Arc<RowSchema>,
    values: Box<[Value]>,
    wire: OnceBox<Bytes>,
}

impl PartialEq for RowSchema {
    /// The same columns in the same order.
    fn eq(&self, other: &Self) -> bool {
        self.names == other.names
    }
}

impl Eq for RowSchema {}

impl RowData {
    /// A row over `schema` with `values` in the schema's order; missing
    /// trailing values are `NULL`, extra ones are dropped.
    pub fn with_schema(schema: Arc<RowSchema>, values: Vec<Value>) -> Self {
        let mut values = values;
        values.resize(schema.len(), Value::Null);
        RowData {
            schema,
            values: values.into_boxed_slice(),
            wire: OnceBox::new(),
        }
    }

    /// The row's schema.
    pub fn schema(&self) -> &Arc<RowSchema> {
        &self.schema
    }

    /// The value of `column`, if the row has the column.
    pub fn get<Q: AsRef<str> + ?Sized>(&self, column: &Q) -> Option<&Value> {
        self.schema
            .position(column.as_ref())
            .map(|index| &self.values[index])
    }

    /// Whether the row has `column`.
    pub fn contains_key<Q: AsRef<str> + ?Sized>(&self, column: &Q) -> bool {
        self.schema.position(column.as_ref()).is_some()
    }

    /// The columns and values, in schema order.
    pub fn iter(&self) -> impl Iterator<Item = (&ColumnName, &Value)> {
        self.schema.names.iter().zip(self.values.iter())
    }

    /// The column names, in schema order.
    pub fn keys(&self) -> impl Iterator<Item = &ColumnName> {
        self.schema.names.iter()
    }

    /// The values, in schema order.
    pub fn values(&self) -> impl Iterator<Item = &Value> {
        self.values.iter()
    }

    /// How many columns.
    pub fn len(&self) -> usize {
        self.values.len()
    }

    /// Whether the row has no columns.
    pub fn is_empty(&self) -> bool {
        self.values.is_empty()
    }

    /// The row's bytes as the transport sends it (its `rowsPatch` put),
    /// empty until the first time the row is sent. The cell is written
    /// once, by whichever thread sends the row first, and read by every
    /// later send in place of serializing the row again
    /// (`client::groups`). That is sound because nothing the bytes are
    /// made of changes while the image lives: the values are never
    /// written after the image is built (a changed row is a new image,
    /// with a cell of its own; a decoded row holds scalars, text and
    /// lists, never a [`Value::Set`], which can grow in place and only
    /// ever belongs to a query's condition), the image belongs to one
    /// table, and its layout fixes the types that table declares (a
    /// migration that adds a column lays the table's rows out again as
    /// new images; one that changes a type stops the server). Two threads
    /// that both find the cell empty write the same bytes, so it does not
    /// matter which of them fills it: the cell is a [`OnceBox`], one
    /// atomic pointer that the first `set` fills and every later one is
    /// refused, and a reader never waits.
    pub fn wire(&self) -> &OnceBox<Bytes> {
        &self.wire
    }

    /// The row as an owned map, for the few places that build a new row
    /// from an old one.
    pub fn to_map(&self) -> HashMap<ColumnName, Value> {
        self.iter()
            .map(|(column, value)| (column.clone(), value.clone()))
            .collect()
    }
}

impl From<HashMap<ColumnName, Value>> for RowData {
    /// A row over a schema of its own, the columns in name order, so two
    /// rows built from equal maps compare equal and hash alike.
    fn from(map: HashMap<ColumnName, Value>) -> Self {
        let mut pairs: Vec<(ColumnName, Value)> = map.into_iter().collect();
        pairs.sort_by(|a, b| a.0.as_str().cmp(b.0.as_str()));
        let schema = RowSchema::new(pairs.iter().map(|(column, _)| column.clone()));
        RowData {
            schema,
            values: pairs.into_iter().map(|(_, value)| value).collect(),
            wire: OnceBox::new(),
        }
    }
}

impl PartialEq for RowData {
    /// Equal as maps: the same columns with the same values, whatever
    /// the schemas' orders.
    fn eq(&self, other: &Self) -> bool {
        if Arc::ptr_eq(&self.schema, &other.schema) {
            return self.values == other.values;
        }
        self.len() == other.len()
            && self
                .iter()
                .all(|(column, value)| other.get(column) == Some(value))
    }
}

impl<Q: AsRef<str> + ?Sized> Index<&Q> for RowData {
    type Output = Value;

    /// The value of a column the row has.
    fn index(&self, column: &Q) -> &Value {
        self.get(column)
            .unwrap_or_else(|| panic!("no column `{}` in the row", column.as_ref()))
    }
}

impl fmt::Debug for RowData {
    /// As a map.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_map().entries(self.iter()).finish()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A row built from a map and one built over a shared schema read
    /// the same, compare equal, and hold every column once.
    #[test]
    fn a_row_reads_as_a_map_whatever_its_schema() {
        let schema = RowSchema::new(["id", "name", "points"].map(ColumnName::from));
        let shared = RowData::with_schema(
            schema.clone(),
            vec![Value::Int(1), Value::from("a"), Value::Int(3)],
        );
        let mapped = RowData::from(HashMap::from([
            (ColumnName::from("points"), Value::Int(3)),
            (ColumnName::from("id"), Value::Int(1)),
            (ColumnName::from("name"), Value::from("a")),
        ]));
        assert_eq!(shared, mapped);
        assert_eq!(shared.get("name"), Some(&Value::from("a")));
        assert_eq!(
            shared.get(&ColumnName::from("points")),
            Some(&Value::Int(3))
        );
        assert_eq!(shared["id"], Value::Int(1));
        assert!(shared.get("missing").is_none());
        assert_eq!(shared.len(), 3);
        assert_eq!(
            mapped.keys().map(ColumnName::as_str).collect::<Vec<_>>(),
            ["id", "name", "points"]
        );
        let short = RowData::with_schema(schema, vec![Value::Int(2)]);
        assert_eq!(
            short.get("points"),
            Some(&Value::Null),
            "missing trailing values are NULL"
        );
        assert_ne!(short, shared);
    }
}

//! The data model the whole engine operates on.
//!
//! Split by concern, re-exported flat — `use xyne_sync::model::*` gives the
//! full vocabulary:
//!
//! - [`value`] — [`Value`] / [`ValueType`], the dynamic value representation
//! - [`schema`] — [`Catalog`] / [`DbTable`] / [`DbColumn`]: the single
//!   authoritative schema home; queries reference tables by name and
//!   resolve them in the catalog
//! - [`query`] — [`SingleTableReadQuery`] / [`WriteQuery`], the `Where`
//!   predicate tree, and the [`SubId`] handle
//! - [`frame`] — row identities, images, the [`DataFrameOperation`] delta
//!   unit, and the engine's shared [`frame::TableFrame`] materialization
//! - [`position`] — where a write, a read, or a frame row sits in the
//!   source's history: one WAL location ([`Lsn`]; [`Snapshot`] for a
//!   read's result)
//! - [`ids`] — the maps and sets keyed by the engine's own small ids,
//!   on a hasher that costs one multiply
//!
//! Structure changes here ripple through the whole engine (these types are
//! index keys in `crate::ivm`), so keep field changes deliberate and discuss
//! them in an issue first — see "Design notes" in the README.

pub mod frame;
pub mod ids;
pub mod position;
pub mod query;
pub mod row;
pub mod schema;
pub mod value;

pub use frame::{DataFrameKey, DataFrameOperation, DataFrameRow};
pub use ids::{IdMap, IdSet};
pub use position::{Lsn, Snapshot};
pub use query::{
    ComparisonOperator, Condition, DeleteQuery, Disjunct, Driver, InsertQuery, Join,
    MultiTableReadQuery, Order, OrderBy, PageRead, SingleTableReadQuery, SubId, UpdateQuery, Where,
    WriteQuery,
};
pub use row::{RowData, RowSchema};
pub use schema::{Catalog, ColumnName, DbColumn, DbTable, PutPlan, TableName};
pub use value::{SharedSet, Value, ValueType};

//! The maps and sets the engine keys by its own small integers: a
//! subscription, row, read or tree id, or a query part. Their hasher is
//! `FxHasher`, one multiply per key, where the default `SipHash` costs
//! twenty times that on the path of every write. Keys that are user data
//! (values, names, filters) keep the default, collision-resistant hasher.

use std::collections::{HashMap, HashSet};
use std::hash::BuildHasherDefault;

use rustc_hash::FxHasher;

/// A map keyed by one of the engine's own ids.
pub type IdMap<K, V> = HashMap<K, V, BuildHasherDefault<FxHasher>>;

/// A set of the engine's own ids.
pub type IdSet<K> = HashSet<K, BuildHasherDefault<FxHasher>>;

//! Runtime values and their types.
//!
//! [`Value`] is the single dynamic value representation used everywhere in
//! the engine: in query predicates, in write payloads, and in materialized
//! rows. The engine keys hash maps by types that embed `Value` (the reverse
//! index is keyed by `Condition`, the shared table frames by
//! `DataFrameKey`), so `Value` must implement `Eq` and `Hash`. `f64` and `HashMap` do not
//! provide those out of the box, hence the manual implementations in this
//! file:
//!
//! - `Float`: `NaN == NaN` and `0.0 == -0.0`, hashed via canonicalized bits,
//!   so equality and hashing stay consistent.
//! - `Map`: equality is order-independent (as for any `HashMap`), so the
//!   hash combines per-entry hashes with an order-independent fold.

use chrono::{NaiveDate, NaiveDateTime};
use std::cmp::Ordering;
use std::collections::{HashMap, HashSet};
use std::hash::{Hash, Hasher};
use std::sync::{Arc, RwLock};

/// A dynamically-typed database value.
///
/// `Int` is `i64` so Postgres `bigint` / `bigserial` identifiers fit
/// natively (decided ahead of the Diesel connector).
#[derive(Debug, Clone)]
pub enum Value {
    Null,
    String(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Date(NaiveDate),
    Datetime(NaiveDateTime),
    List(Vec<Value>),
    Map(std::collections::HashMap<Value, Value>),
    Set(SharedSet),
}

/// The static type of a [`Value`], used to describe columns in a schema.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum ValueType {
    String,
    Int,
    Float,
    Bool,
    Date,
    Datetime,
    List(Box<ValueType>),
    Map(Box<ValueType>, Box<ValueType>),
    /// A point in time carried as milliseconds since the Unix epoch, the
    /// form protocol clients see for `timestamp`, `timestamptz` and `date`
    /// columns; the cell is a [`Value::Int`].
    Timestamp,
    /// A JSON document carried as its text, the form the engine keeps for
    /// `json` and `jsonb` columns; the cell is a [`Value::String`] and the
    /// transport writes it out as the JSON it holds.
    Json,
}

impl Value {
    /// Whether this value is [`Value::Null`].
    pub fn is_null(&self) -> bool {
        matches!(self, Value::Null)
    }

    /// Ordering comparison backing the `GT` / `GTE` / `LT` / `LTE` operators.
    ///
    /// Values compare only within the same variant, except `Int` / `Float`
    /// which coerce to `f64` (lossy above 2⁵³ — mixed-type comparisons of
    /// such magnitudes may tie spuriously; same-variant comparisons are
    /// always exact). Everything else — including anything involving
    /// `Null` — returns `None`, which predicate evaluation treats as
    /// "does not match" (SQL three-valued logic collapsed to `false`).
    pub fn compare(&self, other: &Value) -> Option<Ordering> {
        use Value::*;
        match (self, other) {
            (Int(a), Int(b)) => Some(a.cmp(b)),
            (Float(a), Float(b)) => a.partial_cmp(b),
            (Int(a), Float(b)) => (*a as f64).partial_cmp(b),
            (Float(a), Int(b)) => a.partial_cmp(&(*b as f64)),
            (String(a), String(b)) => Some(a.cmp(b)),
            (Bool(a), Bool(b)) => Some(a.cmp(b)),
            (Date(a), Date(b)) => Some(a.cmp(b)),
            (Datetime(a), Datetime(b)) => Some(a.cmp(b)),
            _ => None,
        }
    }

    /// Equality backing the `EQ` / `NEQ` / `IN` / `NOT_IN` operators:
    /// strict equality plus `Int` / `Float` numeric coercion, so
    /// `Int(5)` equals `Float(5.0)`.
    pub fn loose_eq(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Int(_), Value::Float(_)) | (Value::Float(_), Value::Int(_)) => {
                self.compare(other) == Some(Ordering::Equal)
            }
            _ => self == other,
        }
    }
}

impl Value {
    /// A total order over values consistent with [`Value::eq`] (equal values
    /// compare `Equal`, different variants never do), used to keep the
    /// conditions of a disjunct in one canonical sequence so that two
    /// filters naming the same conditions in a different order normalize
    /// to the same disjunct. Variants are ranked in declaration order; within
    /// a variant the natural order applies, with every `NaN` treated as one
    /// value and `-0.0` as `0.0`, lists compared lexicographically and maps
    /// by their key-sorted entries.
    pub fn canonical_cmp(&self, other: &Value) -> Ordering {
        use Value::*;
        fn rank(value: &Value) -> u8 {
            match value {
                Null => 0,
                String(_) => 1,
                Int(_) => 2,
                Float(_) => 3,
                Bool(_) => 4,
                Date(_) => 5,
                Datetime(_) => 6,
                List(_) => 7,
                Map(_) => 8,
                Set(_) => 9,
            }
        }
        fn canonical_f64(f: f64) -> f64 {
            if f.is_nan() {
                f64::NAN
            } else if f == 0.0 {
                0.0
            } else {
                f
            }
        }
        match (self, other) {
            (Null, Null) => Ordering::Equal,
            (String(a), String(b)) => a.cmp(b),
            (Int(a), Int(b)) => a.cmp(b),
            (Float(a), Float(b)) => canonical_f64(*a).total_cmp(&canonical_f64(*b)),
            (Bool(a), Bool(b)) => a.cmp(b),
            (Date(a), Date(b)) => a.cmp(b),
            (Datetime(a), Datetime(b)) => a.cmp(b),
            (List(a), List(b)) => a
                .iter()
                .zip(b)
                .map(|(x, y)| x.canonical_cmp(y))
                .find(|ordering| *ordering != Ordering::Equal)
                .unwrap_or_else(|| a.len().cmp(&b.len())),
            (Set(a), Set(b)) => a.address().cmp(&b.address()),
            (Map(a), Map(b)) => {
                let mut left: Vec<_> = a.iter().collect();
                let mut right: Vec<_> = b.iter().collect();
                left.sort_by(|x, y| x.0.canonical_cmp(y.0));
                right.sort_by(|x, y| x.0.canonical_cmp(y.0));
                left.iter()
                    .zip(&right)
                    .map(|((ka, va), (kb, vb))| {
                        ka.canonical_cmp(kb).then_with(|| va.canonical_cmp(vb))
                    })
                    .find(|ordering| *ordering != Ordering::Equal)
                    .unwrap_or_else(|| left.len().cmp(&right.len()))
            }
            _ => rank(self).cmp(&rank(other)),
        }
    }
}

/// Floats up to this magnitude are exact integers, so an integral float
/// within it equates to the integer under [`Value::equality_key`].
const EXACT_INTEGER_LIMIT: f64 = 9_007_199_254_740_992.0;

/// A shared, mutable set of values: the operand of a set-valued `IN`, the
/// membership list of a join edge, held by the edge and referenced by the
/// driven part's filter. Two `SharedSet`s are equal only when they are the
/// same set (identity), which keeps a leaf's identity stable while its
/// contents change and lets identical subscriptions share one edge.
/// Members are stored by [`Value::equality_key`], so `Int(5)` and
/// `Float(5.0)` are one member. The set is behind a lock so that a value
/// holding one is `Send`: the engine thread alone mutates it, and the
/// threads that render or serialize a query only read it.
#[derive(Clone, Debug, Default)]
pub struct SharedSet(Arc<RwLock<HashSet<Value>>>);

impl SharedSet {
    /// An empty set.
    pub fn new() -> Self {
        SharedSet::default()
    }

    /// Whether `value` is a member (`NULL` never is).
    pub fn contains(&self, value: &Value) -> bool {
        value
            .equality_key_ref()
            .is_some_and(|key| self.read().contains(&*key))
    }

    /// Add `value`; reports whether it was new (`NULL` is never added).
    pub fn insert(&self, value: &Value) -> bool {
        match value.equality_key() {
            Some(key) => self.write().insert(key),
            None => false,
        }
    }

    /// Remove `value`; reports whether it was a member.
    pub fn remove(&self, value: &Value) -> bool {
        match value.equality_key() {
            Some(key) => self.write().remove(&key),
            None => false,
        }
    }

    /// The current members, as their equality keys, in no particular order.
    pub fn members(&self) -> Vec<Value> {
        self.read().iter().cloned().collect()
    }

    /// How many members the set holds.
    pub fn len(&self) -> usize {
        self.read().len()
    }

    /// Whether the set is empty.
    pub fn is_empty(&self) -> bool {
        self.read().is_empty()
    }

    /// The members for reading; a poisoned lock (a panic while writing)
    /// is read through, since the set is only ever mutated whole.
    fn read(&self) -> std::sync::RwLockReadGuard<'_, HashSet<Value>> {
        self.0
            .read()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    /// The members for writing; see [`SharedSet::read`] on poisoning.
    fn write(&self) -> std::sync::RwLockWriteGuard<'_, HashSet<Value>> {
        self.0
            .write()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    /// The set's identity, for ordering and hashing.
    fn address(&self) -> usize {
        Arc::as_ptr(&self.0) as *const () as usize
    }
}

impl PartialEq for SharedSet {
    /// Identity: the same set, not equal contents.
    fn eq(&self, other: &Self) -> bool {
        Arc::ptr_eq(&self.0, &other.0)
    }
}

impl Eq for SharedSet {}

impl Hash for SharedSet {
    /// Hashes the identity, never the contents.
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.address().hash(state);
    }
}

impl Value {
    /// The key under which a value takes part in equality tests: `None` for
    /// `NULL` (which equals nothing), the integer for an integral float
    /// within exact range (the coercion of [`Value::loose_eq`]), the value
    /// itself otherwise. Two values are `loose_eq` iff their keys are equal,
    /// which is what lets hash maps and sets stand in for equality tests.
    pub fn equality_key(&self) -> Option<Value> {
        self.equality_key_ref().map(std::borrow::Cow::into_owned)
    }

    /// [`Value::equality_key`] without a copy: the value itself borrowed
    /// when it is its own key, an owned integer for an integral float.
    pub fn equality_key_ref(&self) -> Option<std::borrow::Cow<'_, Value>> {
        match self {
            Value::Null => None,
            Value::Float(f) if f.fract() == 0.0 && f.abs() <= EXACT_INTEGER_LIMIT => {
                Some(std::borrow::Cow::Owned(Value::Int(*f as i64)))
            }
            other => Some(std::borrow::Cow::Borrowed(other)),
        }
    }
}

impl PartialEq for Value {
    /// Strict, variant-exact equality (no `Int` / `Float` coercion — that is
    /// [`Value::loose_eq`]). `Float` deviates from raw `f64` semantics by
    /// treating `NaN == NaN` as true, keeping equality a proper equivalence
    /// relation so `Value` can serve as a hash-map key.
    fn eq(&self, other: &Self) -> bool {
        use Value::*;
        match (self, other) {
            (Null, Null) => true,
            (String(a), String(b)) => a == b,
            (Int(a), Int(b)) => a == b,
            (Float(a), Float(b)) => a == b || (a.is_nan() && b.is_nan()),
            (Bool(a), Bool(b)) => a == b,
            (Date(a), Date(b)) => a == b,
            (Datetime(a), Datetime(b)) => a == b,
            (List(a), List(b)) => a == b,
            (Map(a), Map(b)) => a == b,
            (Set(a), Set(b)) => a == b,
            _ => false,
        }
    }
}

impl Eq for Value {}

impl Hash for Value {
    /// Hashes the variant discriminant plus a payload consistent with
    /// [`Value::eq`]: floats go through `canonical_f64_bits`, maps through
    /// `unordered_map_hash`, so equal values always hash identically.
    fn hash<H: Hasher>(&self, state: &mut H) {
        use Value::*;
        std::mem::discriminant(self).hash(state);
        match self {
            Null => {}
            String(s) => s.hash(state),
            Int(i) => i.hash(state),
            Float(f) => canonical_f64_bits(*f).hash(state),
            Bool(b) => b.hash(state),
            Date(d) => d.hash(state),
            Datetime(dt) => dt.hash(state),
            List(items) => items.hash(state),
            Map(entries) => unordered_map_hash(entries).hash(state),
            Set(set) => set.hash(state),
        }
    }
}

/// Bit pattern for hashing an `f64` such that all values that compare equal
/// under [`Value::eq`] hash identically: every NaN collapses to one bit
/// pattern, and `-0.0` collapses to `0.0`.
fn canonical_f64_bits(f: f64) -> u64 {
    if f.is_nan() {
        f64::NAN.to_bits()
    } else if f == 0.0 {
        0
    } else {
        f.to_bits()
    }
}

/// Order-independent hash of a map, matching `HashMap`'s order-independent
/// equality: each entry is hashed on its own and the results are combined
/// with a commutative fold.
pub(crate) fn unordered_map_hash<K: Hash, V: Hash>(map: &HashMap<K, V>) -> u64 {
    unordered_pairs_hash(map.iter())
}

/// The order-independent hash of `(key, value)` pairs: each pair hashed
/// on its own, the results summed, so the same pairs in any order hash
/// alike (a row key laid out on a schema and one built from a map agree).
pub(crate) fn unordered_pairs_hash<K: Hash, V: Hash>(pairs: impl Iterator<Item = (K, V)>) -> u64 {
    pairs
        .map(|(k, v)| {
            let mut h = std::collections::hash_map::DefaultHasher::new();
            k.hash(&mut h);
            v.hash(&mut h);
            h.finish()
        })
        .fold(0u64, u64::wrapping_add)
}

impl From<&str> for Value {
    /// Wraps a borrowed string as [`Value::String`], copying it.
    fn from(s: &str) -> Self {
        Value::String(s.to_owned())
    }
}

impl From<String> for Value {
    /// Wraps an owned string as [`Value::String`].
    fn from(s: String) -> Self {
        Value::String(s)
    }
}

impl From<i32> for Value {
    /// Widens an `i32` into [`Value::Int`] — a convenience for literals and
    /// narrow ids.
    fn from(i: i32) -> Self {
        Value::Int(i64::from(i))
    }
}

impl From<i64> for Value {
    /// Wraps an `i64` as [`Value::Int`].
    fn from(i: i64) -> Self {
        Value::Int(i)
    }
}

impl From<f64> for Value {
    /// Wraps an `f64` as [`Value::Float`].
    fn from(f: f64) -> Self {
        Value::Float(f)
    }
}

impl From<bool> for Value {
    /// Wraps a `bool` as [`Value::Bool`].
    fn from(b: bool) -> Self {
        Value::Bool(b)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::hash_map::DefaultHasher;

    /// Hashes a [`Value`] with the std `DefaultHasher`.
    fn hash_of(v: &Value) -> u64 {
        let mut h = DefaultHasher::new();
        v.hash(&mut h);
        h.finish()
    }

    /// The `Float` special cases (`NaN == NaN`, `0.0 == -0.0`) hash
    /// identically, keeping the `Eq` / `Hash` contract intact.
    #[test]
    fn float_nan_and_zero_equality_matches_hash() {
        let nan_a = Value::Float(f64::NAN);
        let nan_b = Value::Float(-f64::NAN);
        assert_eq!(nan_a, nan_b);
        assert_eq!(hash_of(&nan_a), hash_of(&nan_b));

        let pos_zero = Value::Float(0.0);
        let neg_zero = Value::Float(-0.0);
        assert_eq!(pos_zero, neg_zero);
        assert_eq!(hash_of(&pos_zero), hash_of(&neg_zero));
    }

    /// `Int` / `Float` coercion applies only to [`Value::loose_eq`]; strict
    /// equality (and therefore hashing) stays variant-exact.
    #[test]
    fn int_float_coercion_is_loose_only() {
        assert!(Value::Int(5).loose_eq(&Value::Float(5.0)));
        assert_ne!(Value::Int(5), Value::Float(5.0));
    }

    /// A value, and so a row, a key, a query and a write, can cross a
    /// thread boundary: the shared set is behind a lock, not an `Rc`.
    #[test]
    fn values_are_send_and_sync() {
        fn assert_send_sync<T: Send + Sync>() {}
        assert_send_sync::<Value>();
        assert_send_sync::<SharedSet>();
        assert_send_sync::<crate::model::DataFrameRow>();
        assert_send_sync::<crate::model::DataFrameKey>();
        assert_send_sync::<crate::model::WriteQuery>();
        assert_send_sync::<crate::model::MultiTableReadQuery>();
        assert_send_sync::<crate::ivm::Delta>();
    }

    /// [`Value::compare`] returns `None` for anything involving `Null`,
    /// including `Null` vs `Null`.
    #[test]
    fn null_compares_with_nothing() {
        assert_eq!(Value::Null.compare(&Value::Null), None);
        assert_eq!(Value::Null.compare(&Value::Int(1)), None);
    }
}

//! The query model: read (subscription) queries, write queries, and the
//! predicate tree (`Where` / `Condition`) shared by both.
//!
//! This is deliberately the engine's own representation rather than raw SQL
//! strings: predicates must be inspectable (to index them) and comparable
//! (to route writes), neither of which text allows. The SQL parser
//! (`crate::parser`) produces these types from query text.

use super::frame::{DataFrameKey, DataFrameRow};
use super::schema::{ColumnName, TableName};
use super::value::Value;

/// A subscription query: `SELECT * FROM table WHERE … ORDER BY … LIMIT …`.
///
/// `Eq` + `Hash` let structurally identical queries be compared and deduped
/// — registration uses this to serve an identical already-registered query
/// straight from the shared frame instead of re-running it; the IVM
/// forward index itself is keyed by subscription uuid.
///
/// - `table`: table name, resolved against the [`super::schema::Catalog`].
/// - `filter`: the `WHERE` predicate tree.
/// - `order_by`: the `ORDER BY` clause, one or more columns compared in
///   turn; the parser defaults it to the first declared pkey column,
///   ascending.
/// - `limit`: the `LIMIT` row cap; `u32::MAX` is the parser's spelling of
///   "no limit".
///
/// `order_by` and `limit` take part in the structural equality that twin
/// sharing matches on, so programmatic queries must reproduce the parser's
/// conventions exactly to share materialization with parsed ones.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct SingleTableReadQuery {
    pub table: TableName,
    pub filter: Where,
    pub order_by: Vec<OrderBy>,
    pub limit: u32,
}

/// The engine's handle for one registered subscription: a `u64` handed out
/// by `register_query`, unique for the life of the engine and never reused.
/// The layer above the engine (the transport) maps a client's own
/// subscription ids to it; the engine never sees client ids.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct SubId(pub u64);

impl std::fmt::Display for SubId {
    /// The bare number.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

/// Which side of a join edge drives it: whose held rows decide the join
/// values that are *referenced*. The other side, the driven one, holds
/// only rows matching a referenced value (its filter carries
/// `driven_column IN <referenced values>`), so it is never read whole.
///
/// - `Main`: the enclosing node's rows pick the sub rows (the client's
///   `related`, a LEFT join, and an inner join evaluated from the parent).
/// - `Sub`: the sub rows pick the enclosing node's rows (a RIGHT join, and
///   an inner join evaluated from the child, `whereExists` as
///   translated).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Driver {
    Main,
    Sub,
}

/// One join edge of a [`MultiTableReadQuery`]: rows of `sub`'s main table
/// attach to rows of the enclosing node where
/// `sub.<sub_table_column> = enclosing.<main_table_column>`.
///
/// `sub` is a full multi-table query, so a leaf is a node whose `joins`
/// are empty and nesting costs nothing. Two flags spell the edge out:
///
/// - `driver`: which side's rows decide the referenced join values; the
///   other side holds only rows matching one of them.
/// - `is_inner`: whether the driver's rows need a match to be shown. An
///   outer edge keeps them (the other side being null is fine for the
///   driver's row); an inner edge shows a driver row only while a driven
///   row carries its join value.
///
/// | `driver` | `is_inner` | Reads as | Meaning |
/// |---|---|---|---|
/// | `Main` | `false` | LEFT | main rows stand; sub rows exist for referenced values and are shown under a shown main row |
/// | `Sub` | `false` | RIGHT | sub rows stand; main rows exist only for values some sub row carries |
/// | `Sub` | `true` | INNER, from the sub | main rows exist only for values some sub row carries; sub rows shown under a shown main row |
/// | `Main` | `true` | INNER, from the main | sub rows exist for referenced values; a main row is shown only while a sub row matches it |
///
/// The two inner forms show the client the same rows and differ only in
/// which side is read whole, which is the choice a planner makes by
/// flipping `driver`; nothing else in the tree moves when it does. An
/// inner edge's test may be placed anywhere in the enclosing node's
/// `WHERE` through a [`ComparisonOperator::EXISTS`] leaf naming it;
/// unnamed, it is conjoined. Below the root, the sub node of an edge the
/// main drives may carry an `order_by` / `limit` of its own: it is a
/// window **per enclosing row**, the best *n* sub rows for each value the
/// enclosing rows reference (`related` with a limit, in the client's terms). A
/// sub node that drives its edge is read whole, so its limit is an
/// ordinary window on that node. A `NULL` (or missing) join value never
/// matches, consistent with the engine's NULL semantics.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Join {
    pub sub: MultiTableReadQuery,
    pub main_table_column: ColumnName,
    pub sub_table_column: ColumnName,
    pub driver: Driver,
    pub is_inner: bool,
}

impl Join {
    /// Builds an edge attaching `sub` on
    /// `enclosing.<main_table_column> = sub.<sub_table_column>`, driven
    /// by `driver`, inner or outer.
    pub fn new(
        sub: MultiTableReadQuery,
        main_table_column: impl Into<ColumnName>,
        sub_table_column: impl Into<ColumnName>,
        driver: Driver,
        is_inner: bool,
    ) -> Self {
        Join {
            sub,
            main_table_column: main_table_column.into(),
            sub_table_column: sub_table_column.into(),
            driver,
            is_inner,
        }
    }

    /// A LEFT edge: the main rows drive and stand on their own.
    pub fn left(
        sub: MultiTableReadQuery,
        main_table_column: impl Into<ColumnName>,
        sub_table_column: impl Into<ColumnName>,
    ) -> Self {
        Join::new(
            sub,
            main_table_column,
            sub_table_column,
            Driver::Main,
            false,
        )
    }

    /// A RIGHT edge: the sub rows drive and stand on their own.
    pub fn right(
        sub: MultiTableReadQuery,
        main_table_column: impl Into<ColumnName>,
        sub_table_column: impl Into<ColumnName>,
    ) -> Self {
        Join::new(sub, main_table_column, sub_table_column, Driver::Sub, false)
    }

    /// An INNER edge evaluated from the sub: the sub rows drive and are
    /// shown only under a shown main row (`whereExists`).
    pub fn inner(
        sub: MultiTableReadQuery,
        main_table_column: impl Into<ColumnName>,
        sub_table_column: impl Into<ColumnName>,
    ) -> Self {
        Join::new(sub, main_table_column, sub_table_column, Driver::Sub, true)
    }

    /// An INNER edge evaluated from the main: the main rows drive and are
    /// shown only while a sub row matches them.
    pub fn inner_from_main(
        sub: MultiTableReadQuery,
        main_table_column: impl Into<ColumnName>,
        sub_table_column: impl Into<ColumnName>,
    ) -> Self {
        Join::new(sub, main_table_column, sub_table_column, Driver::Main, true)
    }

    /// Whether the main rows drive the edge (the sub is the driven side).
    pub fn main_drives(&self) -> bool {
        self.driver == Driver::Main
    }
}

/// How a node with a `LIMIT` that drives an inner edge — a page whose
/// rows the edge admits or rejects — is read. The planner decides from
/// the node's count; for every other node the value has no effect.
///
/// - `Whole`: every row the node's filter matches is read in one go and
///   held; the `LIMIT` is applied in memory. The rows the edge rejects
///   stay held, so the driven side keeps its `IN` restriction exactly.
/// - `Batched`: the window is read in batches that double from one round
///   to the next; the rows the edge rejects are dropped, and the driven
///   side routes on its own filter, looking the driver up when a write
///   concerns a dropped row.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum PageRead {
    Whole,
    #[default]
    Batched,
}

/// A multi-table subscription: a tree whose every node is a single-table
/// query and every edge a [`Join`]. The root is the query the client
/// subscribed to; its `order_by` / `limit` apply to the root's rows. A
/// node's parts are numbered by the position of their edge in `joins`.
/// `page` says how the node is read when it is a page that drives an
/// inner edge ([`PageRead`]). Structurally identical trees compare equal,
/// the basis of sharing; two trees that differ only in an edge's `driver`
/// or a node's `page` are two trees.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct MultiTableReadQuery {
    pub main_table: SingleTableReadQuery,
    pub joins: Vec<Join>,
    pub page: PageRead,
}

impl MultiTableReadQuery {
    /// A tree of one node: `main_table` with no joins.
    pub fn single(main_table: SingleTableReadQuery) -> Self {
        MultiTableReadQuery {
            main_table,
            joins: Vec::new(),
            page: PageRead::default(),
        }
    }

    /// A tree of `main_table` with `joins` under it.
    pub fn new(main_table: SingleTableReadQuery, joins: Vec<Join>) -> Self {
        MultiTableReadQuery {
            main_table,
            joins,
            page: PageRead::default(),
        }
    }

    /// The node at `path` (the join positions from the root).
    pub fn node_at(&self, path: &[usize]) -> Option<&MultiTableReadQuery> {
        let mut node = self;
        for &step in path {
            node = &node.joins.get(step)?.sub;
        }
        Some(node)
    }

    /// The node at `path` (the join positions from the root), mutably.
    pub fn node_at_mut(&mut self, path: &[usize]) -> Option<&mut MultiTableReadQuery> {
        let mut node = self;
        for &step in path {
            node = &mut node.joins.get_mut(step)?.sub;
        }
        Some(node)
    }

    /// Whether the tree has any edge.
    pub fn has_joins(&self) -> bool {
        !self.joins.is_empty()
    }

    /// The positions in `joins` of the node's inner edges, in order: what
    /// an `EXISTS` leaf's index counts through.
    pub fn inner_positions(&self) -> impl Iterator<Item = usize> + '_ {
        self.joins
            .iter()
            .enumerate()
            .filter(|(_, join)| join.is_inner)
            .map(|(position, _)| position)
    }

    /// The node's `index`-th inner edge: the one an `EXISTS` leaf with
    /// that index names.
    pub fn inner_join(&self, index: usize) -> Option<&Join> {
        self.joins.iter().filter(|join| join.is_inner).nth(index)
    }

    /// Every table of the tree, the node's own first and then each sub's
    /// in join order, depth first; a table used by two nodes is listed
    /// twice.
    pub fn tables(&self) -> Vec<&TableName> {
        let mut out = vec![&self.main_table.table];
        for join in &self.joins {
            out.extend(join.sub.tables());
        }
        out
    }
}

/// A write against a table — exactly one of insert / update / delete.
///
/// Writes speak the same vocabulary as the operations the engine emits: the
/// affected row is identified by a [`DataFrameKey`] and its new image
/// carried as a [`DataFrameRow`] — there is no separate record type.
#[allow(non_camel_case_types)]
#[derive(Debug, Clone, PartialEq)]
pub enum WriteQuery {
    UPDATE(UpdateQuery),
    DELETE(DeleteQuery),
    INSERT(InsertQuery),
}

/// Update the row identified by `pkey_value`.
///
/// v1 constraint: `record` must carry the **complete new row image** —
/// every column, primary-key columns included, never just the changed
/// ones. Predicates are evaluated against it, so a partial image would
/// silently mis-evaluate conditions on omitted columns. The one exception:
/// a column the change feed reports unchanged (a large value the update
/// did not touch) may be absent, and the engine completes it from the
/// image it holds when it holds the row. Supporting partial
/// updates needs a read-before-write against storage (see the roadmap in
/// the README).
#[derive(Debug, Clone, PartialEq)]
pub struct UpdateQuery {
    pub table: TableName,
    pub pkey_value: DataFrameKey,
    pub record: DataFrameRow,
}

/// Delete the row identified by `pkey_value`. Carries no row data — only
/// identity — so it can never move a row *into* a result set, only out.
#[derive(Debug, Clone, PartialEq)]
pub struct DeleteQuery {
    pub table: TableName,
    pub pkey_value: DataFrameKey,
}

/// Insert a new row (upsert semantics in v1: inserting an existing key
/// replaces the row). `record` carries the complete row image — every
/// column, primary-key columns included.
#[derive(Debug, Clone, PartialEq)]
pub struct InsertQuery {
    pub table: TableName,
    pub pkey_value: DataFrameKey,
    pub record: DataFrameRow,
}

/// A leaf predicate: `column <op> value`.
///
/// This is the key of the IVM reverse index, hence `Eq` + `Hash`.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Condition {
    pub column: ColumnName,
    pub comparison_operator: ComparisonOperator,
    pub value: Value,
}

impl PartialOrd for Condition {
    /// Delegates to [`Ord`].
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Condition {
    /// The canonical order of conditions inside a [`Disjunct`]: by column,
    /// then operator, then [`Value::canonical_cmp`]; consistent with `Eq`.
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.column
            .cmp(&other.column)
            .then_with(|| self.comparison_operator.cmp(&other.comparison_operator))
            .then_with(|| self.value.canonical_cmp(&other.value))
    }
}

/// A predicate tree of [`Condition`]s combined with `AND` / `OR`.
///
/// `AND(vec![])` is vacuously true (a query with no filter — a full-table
/// subscription); `OR(vec![])` is vacuously false, matching SQL conventions.
///
/// This is the *raw* shape, exactly as the user's query states it. The
/// engine routes on the derived DNF shape instead — see [`Where::to_dnf`].
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Where {
    Condition(Condition),
    AND(Vec<Where>),
    OR(Vec<Where>),
}

/// One conjunctive clause of a DNF-normalized filter: the disjunct matches a
/// row iff **every** condition in it matches. A disjunct with no conditions
/// is vacuously true.
///
/// A full filter in DNF is an OR of disjuncts — represented simply as
/// `Vec<Disjunct>`, where the empty vec is vacuously false (`OR` of
/// nothing). Produced by [`Where::to_dnf`]; the IVM indexes and counts these
/// rather than walking `Where` trees per write.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Disjunct {
    pub conditions: Vec<Condition>,
}

impl Disjunct {
    /// A disjunct from its conditions in **canonical form**: duplicates
    /// removed and the rest sorted by [`Condition`]'s order, so two filters
    /// naming the same conditions in any order produce equal disjuncts and
    /// share one counter in the routing index.
    pub fn new(mut conditions: Vec<Condition>) -> Self {
        conditions.sort();
        conditions.dedup();
        Disjunct { conditions }
    }
}

/// The comparison operator of a leaf [`Condition`]: equality, ordering,
/// set-membership and null tests. Negation lives here (`NEQ`, `NOT_IN`,
/// `IS_NOT`) — the [`Where`] tree has no `NOT` node.
///
/// `IS` and `IS_NOT` are SQL's `IS [NOT] NULL`: the operand must be
/// `Null` (the parser accepts nothing else after `IS`); with any other
/// operand the condition follows the convention of `= NULL` and is simply
/// never true. `IS` holds for a `NULL` or absent column, `IS_NOT` for a
/// present, non-`NULL` one.
///
/// `EXISTS` is the existence test of a multi-table query, placed where the
/// author wants it in the tree: `column EXISTS Int(i)` names the node's
/// `i`-th inner edge (counting the edges with `is_inner` set, in the order
/// of `joins`; the count is unchanged by which side drives), whose
/// `main_table_column` must be `column`. At registration the join layer
/// honors it by the edge's driver: bound in place into `column IN <set>`,
/// the set of join values the sub currently produces, when the sub drives;
/// evaluated as "a sub row matches this row" when the main drives. Unbound,
/// or with any other operand, it is never true.
#[allow(non_camel_case_types)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum ComparisonOperator {
    EQ,
    NEQ,
    GT,
    GTE,
    LT,
    LTE,
    IN,
    NOT_IN,
    IS,
    IS_NOT,
    EXISTS,
}

/// One `column ASC|DESC` of an `ORDER BY`; a query's clause is a list of
/// these, later columns breaking the earlier ones' ties.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct OrderBy {
    pub column: ColumnName,
    pub direction: Order,
}

impl From<OrderBy> for Vec<OrderBy> {
    /// A one-column clause.
    fn from(order_by: OrderBy) -> Self {
        vec![order_by]
    }
}

/// Sort direction of an [`OrderBy`] clause: ascending or descending.
#[allow(non_camel_case_types)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Order {
    ASC,
    DESC,
}

impl Condition {
    /// Builds a `column <op> value` leaf condition.
    pub fn new(
        column: impl Into<ColumnName>,
        comparison_operator: ComparisonOperator,
        value: impl Into<Value>,
    ) -> Self {
        Condition {
            column: column.into(),
            comparison_operator,
            value: value.into(),
        }
    }
}

impl Where {
    /// Convenience for a single-condition filter.
    pub fn condition(
        column: impl Into<ColumnName>,
        op: ComparisonOperator,
        value: impl Into<Value>,
    ) -> Self {
        Where::Condition(Condition::new(column, op, value))
    }

    /// `column IS NULL`.
    pub fn is_null(column: impl Into<ColumnName>) -> Self {
        Where::condition(column, ComparisonOperator::IS, Value::Null)
    }

    /// `column IS NOT NULL`.
    pub fn is_not_null(column: impl Into<ColumnName>) -> Self {
        Where::condition(column, ComparisonOperator::IS_NOT, Value::Null)
    }

    /// The existence test of the node's `index`-th inner edge, on the
    /// node's join column `column`; see [`ComparisonOperator::EXISTS`].
    pub fn exists(column: impl Into<ColumnName>, index: usize) -> Self {
        Where::condition(column, ComparisonOperator::EXISTS, Value::Int(index as i64))
    }

    /// Whether `condition` is one of the tree's leaves.
    pub fn contains(&self, condition: &Condition) -> bool {
        self.leaf_conditions()
            .into_iter()
            .any(|leaf| leaf == condition)
    }

    /// Whether the tree requires `condition`: the leaf stands on a path
    /// of `AND`s from the root, so no row satisfies the tree without it.
    /// A leaf only found under an `OR` is not required (another branch
    /// may hold instead).
    pub fn requires(&self, condition: &Condition) -> bool {
        match self {
            Where::Condition(leaf) => leaf == condition,
            Where::AND(children) => children.iter().any(|child| child.requires(condition)),
            Where::OR(_) => false,
        }
    }

    /// All leaf [`Condition`]s of the tree, in depth-first order — the raw
    /// syntactic leaves, duplicates and dead branches included.
    ///
    /// Note this is *not* what drives routing: the IVM indexes the
    /// [`Where::to_dnf`] disjunct conditions instead, which collapse
    /// duplicates and drop conditions in unsatisfiable branches (for
    /// `a = 1 AND FALSE`, this returns `a = 1` while the DNF is empty and
    /// nothing gets indexed).
    pub fn leaf_conditions(&self) -> Vec<&Condition> {
        let mut out = Vec::new();
        self.collect_leaves(&mut out);
        out
    }

    /// Recursive worker for [`Where::leaf_conditions`]: pushes every leaf of
    /// this subtree onto `out` in depth-first order.
    fn collect_leaves<'a>(&'a self, out: &mut Vec<&'a Condition>) {
        match self {
            Where::Condition(c) => out.push(c),
            Where::AND(children) | Where::OR(children) => {
                for child in children {
                    child.collect_leaves(out);
                }
            }
        }
    }

    /// Replace every leaf equal to `old` with `new`, in place — the seam
    /// for editing one condition's value list (a join's `IN`) without
    /// rebuilding the tree.
    pub fn replace_condition(&mut self, old: &Condition, new: &Condition) {
        match self {
            Where::Condition(condition) => {
                if condition == old {
                    *condition = new.clone();
                }
            }
            Where::AND(children) | Where::OR(children) => {
                for child in children {
                    child.replace_condition(old, new);
                }
            }
        }
    }

    /// The tree with every leaf `is_true` accepts taken as true: an `OR`
    /// holding one is true, a clause that became true drops out of its
    /// `AND`, and a tree that is nothing but true is the empty `AND`.
    pub fn assuming_true(&self, is_true: &dyn Fn(&Condition) -> bool) -> Where {
        self.assume(is_true)
            .unwrap_or_else(|| Where::AND(Vec::new()))
    }

    /// [`Where::assuming_true`]'s recursion; `None` is "true".
    fn assume(&self, is_true: &dyn Fn(&Condition) -> bool) -> Option<Where> {
        match self {
            Where::Condition(condition) => {
                (!is_true(condition)).then(|| Where::Condition(condition.clone()))
            }
            Where::AND(children) => {
                let kept: Vec<Where> = children
                    .iter()
                    .filter_map(|child| child.assume(is_true))
                    .collect();
                (!kept.is_empty()).then_some(Where::AND(kept))
            }
            Where::OR(children) => {
                let mut kept = Vec::with_capacity(children.len());
                for child in children {
                    kept.push(child.assume(is_true)?);
                }
                Some(Where::OR(kept))
            }
        }
    }

    /// Can this tree evaluate to `true` with *zero* leaf conditions
    /// matching? True for `AND(vec![])` (no filter at all) and for shapes
    /// like `x OR TRUE`. Equivalent to `to_dnf` containing an empty
    /// disjunct, without building the DNF.
    pub fn vacuously_satisfiable(&self) -> bool {
        match self {
            Where::Condition(_) => false,
            Where::AND(children) => children.iter().all(Where::vacuously_satisfiable),
            Where::OR(children) => children.iter().any(Where::vacuously_satisfiable),
        }
    }

    /// Normalize to disjunctive normal form: an OR of [`Disjunct`]s (each an
    /// AND of leaf conditions), logically equivalent to this tree.
    ///
    /// There is no `NOT` node in `Where` (negation lives inside leaf
    /// operators like `NEQ` / `NOT_IN`), so this is plain distribution of
    /// AND over OR. Identities fall out naturally: `AND(vec![])` becomes one
    /// empty disjunct (always true), `OR(vec![])` becomes zero disjuncts
    /// (never true), and a duplicated condition within one disjunct is
    /// collapsed so each disjunct's length is its exact match requirement.
    ///
    /// The result can be exponential in the alternation depth of the tree —
    /// `(a1 OR b1) AND … AND (an OR bn)` yields `2^n` disjuncts. Typical
    /// subscription filters (ANDs with small OR/IN sprinkles) stay tiny;
    /// a size cap with a tree-evaluation fallback is deliberately deferred
    /// until real workloads show the need.
    /// Every disjunct comes out in canonical form ([`Disjunct::new`]), so
    /// condition order in the source filter never affects identity.
    ///
    /// The `AND` arm folds the cross product starting from TRUE (one empty
    /// disjunct); an always-false child empties the accumulator, making the
    /// whole AND false.
    pub fn to_dnf(&self) -> Vec<Disjunct> {
        match self {
            Where::Condition(condition) => vec![Disjunct::new(vec![condition.clone()])],
            Where::OR(children) => children.iter().flat_map(Where::to_dnf).collect(),
            Where::AND(children) => {
                let mut accumulated = vec![Disjunct::new(Vec::new())];
                for child in children {
                    let child_dnf = child.to_dnf();
                    let mut next = Vec::with_capacity(accumulated.len() * child_dnf.len());
                    for left in &accumulated {
                        for right in &child_dnf {
                            let mut conditions = left.conditions.clone();
                            conditions.extend(right.conditions.iter().cloned());
                            next.push(Disjunct::new(conditions));
                        }
                    }
                    accumulated = next;
                }
                accumulated
            }
        }
    }
}

impl OrderBy {
    /// Builds an `ORDER BY column direction` clause.
    pub fn new(column: impl Into<ColumnName>, direction: Order) -> Self {
        OrderBy {
            column: column.into(),
            direction,
        }
    }
}

impl SingleTableReadQuery {
    /// Builds a subscription query from its four clauses; `order_by`
    /// takes one [`OrderBy`] or a list of them.
    pub fn new(
        table: impl Into<TableName>,
        filter: Where,
        order_by: impl Into<Vec<OrderBy>>,
        limit: u32,
    ) -> Self {
        SingleTableReadQuery {
            table: table.into(),
            filter,
            order_by: order_by.into(),
            limit,
        }
    }
}

impl WriteQuery {
    /// The name of the table this write targets.
    pub fn table(&self) -> &TableName {
        match self {
            WriteQuery::UPDATE(q) => &q.table,
            WriteQuery::DELETE(q) => &q.table,
            WriteQuery::INSERT(q) => &q.table,
        }
    }

    /// The identity of the affected row.
    pub fn pkey_value(&self) -> &DataFrameKey {
        match self {
            WriteQuery::UPDATE(q) => &q.pkey_value,
            WriteQuery::DELETE(q) => &q.pkey_value,
            WriteQuery::INSERT(q) => &q.pkey_value,
        }
    }

    /// The complete row image *after* this write — the record exactly as
    /// carried, which must hold every column, primary-key columns included
    /// (see [`UpdateQuery`]); nothing is merged in here. `None` for
    /// deletes, which carry no row data.
    ///
    /// Predicates are evaluated against this image, so a record missing a
    /// column would silently mis-evaluate conditions on it.
    pub fn new_row_image(&self) -> Option<&DataFrameRow> {
        match self {
            WriteQuery::UPDATE(q) => Some(&q.record),
            WriteQuery::INSERT(q) => Some(&q.record),
            WriteQuery::DELETE(_) => None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use ComparisonOperator::EQ;

    /// Shorthand for a single `column = value` leaf [`Where`].
    fn c(column: &str, value: i32) -> Where {
        Where::condition(column, EQ, value)
    }

    /// Builds the expected [`Disjunct`] of `column = value` conditions.
    fn disjunct(pairs: &[(&str, i32)]) -> Disjunct {
        Disjunct {
            conditions: pairs
                .iter()
                .map(|(column, value)| Condition::new(*column, EQ, *value))
                .collect(),
        }
    }

    /// A lone leaf condition normalizes to exactly one one-condition disjunct.
    #[test]
    fn single_condition_is_one_singleton_disjunct() {
        assert_eq!(c("a", 1).to_dnf(), vec![disjunct(&[("a", 1)])]);
    }

    /// OR children concatenate their disjuncts, and AND distributes over OR:
    /// `(a OR b) AND (c OR d)` yields the cross product `ac, ad, bc, bd`.
    #[test]
    fn or_concatenates_and_distributes_over_and() {
        let or = Where::OR(vec![c("a", 1), c("b", 2)]);
        assert_eq!(
            or.to_dnf(),
            vec![disjunct(&[("a", 1)]), disjunct(&[("b", 2)])]
        );

        let cross = Where::AND(vec![
            Where::OR(vec![c("a", 1), c("b", 2)]),
            Where::OR(vec![c("c", 3), c("d", 4)]),
        ]);
        assert_eq!(
            cross.to_dnf(),
            vec![
                disjunct(&[("a", 1), ("c", 3)]),
                disjunct(&[("a", 1), ("d", 4)]),
                disjunct(&[("b", 2), ("c", 3)]),
                disjunct(&[("b", 2), ("d", 4)]),
            ]
        );
    }

    /// The boolean identities: TRUE (`AND(vec![])`) is one empty disjunct,
    /// FALSE (`OR(vec![])`) is no disjuncts, `x AND FALSE` annihilates to
    /// FALSE, and `x OR TRUE` keeps its vacuous disjunct.
    #[test]
    fn identities_true_false_and_annihilation() {
        assert_eq!(Where::AND(vec![]).to_dnf(), vec![disjunct(&[])]);
        assert_eq!(Where::OR(vec![]).to_dnf(), Vec::<Disjunct>::new());
        assert_eq!(
            Where::AND(vec![c("x", 1), Where::OR(vec![])]).to_dnf(),
            Vec::<Disjunct>::new()
        );
        assert_eq!(
            Where::OR(vec![c("x", 1), Where::AND(vec![])]).to_dnf(),
            vec![disjunct(&[("x", 1)]), disjunct(&[])]
        );
    }

    /// `a AND a` must require ONE match, not two — the disjunct's length is
    /// the engine's exact firing threshold.
    #[test]
    fn duplicate_condition_in_a_conjunction_collapses() {
        assert_eq!(
            Where::AND(vec![c("a", 1), c("a", 1)]).to_dnf(),
            vec![disjunct(&[("a", 1)])]
        );
    }
}

//! Table schema: the catalog, tables, and columns.
//!
//! The schema has one authoritative home — the [`Catalog`] — and resolves by
//! name at every level: the catalog maps table names to [`DbTable`]s, and
//! each table maps column names to [`DbColumn`]s. Queries reference their
//! table **by name**; nothing else carries schema copies, so a migration
//! cannot leave two halves of the engine disagreeing about what a table
//! looks like.

use std::collections::HashMap;
use std::sync::Arc;

use super::row::RowSchema;

use super::value::ValueType;

/// The name of a table, as its own type so it can never be confused with
/// the other strings the engine passes around (subscription ids, column
/// names).
///
/// Constructed from any string-ish value; compares, orders, and hashes
/// exactly like the underlying name, maps keyed by `TableName` accept a
/// plain `&str` for lookups, and it compares directly against string
/// literals. The name is shared, so a clone is a reference count and the
/// rows of a table carry their table's name without copying it.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct TableName(Arc<str>);

impl TableName {
    /// The name as a borrowed string slice.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl From<&str> for TableName {
    /// Wraps a borrowed name.
    fn from(name: &str) -> Self {
        TableName(Arc::from(name))
    }
}

impl From<String> for TableName {
    /// Wraps an owned name.
    fn from(name: String) -> Self {
        TableName(Arc::from(name))
    }
}

impl std::borrow::Borrow<str> for TableName {
    /// Lets maps keyed by [`TableName`] be queried with a plain `&str`.
    fn borrow(&self) -> &str {
        &self.0
    }
}

impl PartialEq<str> for TableName {
    /// Compares against a bare string name.
    fn eq(&self, other: &str) -> bool {
        &*self.0 == other
    }
}

impl PartialEq<&str> for TableName {
    /// Compares against a bare string name.
    fn eq(&self, other: &&str) -> bool {
        &*self.0 == *other
    }
}

impl std::fmt::Display for TableName {
    /// Renders as the bare name, honoring width/alignment format flags.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.pad(&self.0)
    }
}

/// The name of a column, as its own type so it can never be confused with
/// the other strings the engine passes around (table names, subscription
/// ids).
///
/// Constructed from any string-ish value; compares, orders, and hashes
/// exactly like the underlying name, maps keyed by `ColumnName` accept a
/// plain `&str` for lookups, and it compares directly against string
/// literals. The name is shared, so a row image (a map keyed by column
/// name) is cloned without allocating a name per column, and decoders take
/// their names from the catalog instead of allocating one per row.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct ColumnName(Arc<str>);

impl ColumnName {
    /// The name as a borrowed string slice.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl From<&str> for ColumnName {
    /// Wraps a borrowed name.
    fn from(name: &str) -> Self {
        ColumnName(Arc::from(name))
    }
}

impl From<String> for ColumnName {
    /// Wraps an owned name.
    fn from(name: String) -> Self {
        ColumnName(Arc::from(name))
    }
}

impl AsRef<str> for ColumnName {
    /// The name as a string slice.
    fn as_ref(&self) -> &str {
        &self.0
    }
}

impl std::borrow::Borrow<str> for ColumnName {
    /// Lets maps keyed by [`ColumnName`] be queried with a plain `&str`.
    fn borrow(&self) -> &str {
        &self.0
    }
}

impl PartialEq<str> for ColumnName {
    /// Compares against a bare string name.
    fn eq(&self, other: &str) -> bool {
        &*self.0 == other
    }
}

impl PartialEq<&str> for ColumnName {
    /// Compares against a bare string name.
    fn eq(&self, other: &&str) -> bool {
        &*self.0 == *other
    }
}

impl std::fmt::Display for ColumnName {
    /// Renders as the bare name, honoring width/alignment format flags.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.pad(&self.0)
    }
}

/// A column: the table it belongs to, its name, and its static type.
///
/// `table` is stamped by [`DbTable::new`] when the column joins a table —
/// build columns with [`DbColumn::new`] (unqualified) and let the table
/// qualify them, so a column and its owning table can never disagree.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct DbColumn {
    pub table: TableName,
    pub name: ColumnName,
    pub r#type: ValueType,
}

/// A table: its name, its columns resolvable by name, and the names of the
/// columns forming the primary key (in declaration order — the first pkey
/// entry drives the default `ORDER BY`).
///
/// `pkey` entries reference `columns` by name — the constructor enforces
/// that, along with uniqueness, so a `DbTable` built through [`DbTable::new`]
/// is always internally consistent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DbTable {
    pub name: TableName,
    pub pkey: Vec<ColumnName>,
    pub columns: HashMap<ColumnName, DbColumn>,
    /// The layout every row decoded from this table shares: the key
    /// columns first, the rest by name.
    row_schema: Arc<RowSchema>,
    /// The layout of the table's keys: the key columns, in order.
    key_schema: Arc<RowSchema>,
    /// What the transport writes around the values of a row on
    /// `row_schema`, worked out once for the table.
    put_plan: Arc<PutPlan>,
}

/// The part of a row's `rowsPatch` put that depends on its table and not
/// on the row: `{"op":"put","tableName":…,"value":{` and, for each column
/// of the table's row layout in its order, the column's name as a JSON
/// key followed by `:` (and preceded by `,` after the first) with the
/// type the column declares. A row on that layout is then written as the
/// head, each column's key bytes and value, and `}}`, with no lookup or
/// escaping per cell (`client::wire::write_put`). Built by
/// [`DbTable::new`], so once per table when the catalog is read and once
/// more when a migration adds the table or a column to it.
#[derive(Debug, PartialEq, Eq)]
pub struct PutPlan {
    head: Box<[u8]>,
    columns: Box<[(Box<[u8]>, ValueType)]>,
}

impl PutPlan {
    /// The plan for rows of `table` laid out on `layout`, whose names
    /// are all keys of `columns`.
    fn new(table: &TableName, layout: &RowSchema, columns: &HashMap<ColumnName, DbColumn>) -> Self {
        let mut head = b"{\"op\":\"put\",\"tableName\":".to_vec();
        json_string(&mut head, table.as_str());
        head.extend_from_slice(b",\"value\":{");
        let columns = layout
            .names()
            .iter()
            .enumerate()
            .map(|(index, name)| {
                let mut key = Vec::with_capacity(name.as_str().len() + 4);
                if index > 0 {
                    key.push(b',');
                }
                json_string(&mut key, name.as_str());
                key.push(b':');
                let declared = columns
                    .get(name)
                    .map(|column| column.r#type.clone())
                    .expect("a table's row layout is made of its columns");
                (key.into_boxed_slice(), declared)
            })
            .collect();
        PutPlan {
            head: head.into_boxed_slice(),
            columns,
        }
    }

    /// `{"op":"put","tableName":…,"value":{`.
    pub fn head(&self) -> &[u8] {
        &self.head
    }

    /// Per column of the row layout, in its order: the JSON key bytes
    /// written before the value, and the type the column declares.
    pub fn columns(&self) -> &[(Box<[u8]>, ValueType)] {
        &self.columns
    }
}

/// Append `text` as a JSON string.
fn json_string(out: &mut Vec<u8>, text: &str) {
    serde_json::to_writer(&mut *out, text).expect("a string always serializes into a Vec");
}

/// The authoritative set of table schemas, by name.
///
/// The parser resolves and validates statements against it; anything else
/// needing schema (initial result sets, type checks) looks tables up here
/// rather than carrying copies.
#[derive(Debug, Clone, Default)]
pub struct Catalog {
    tables: HashMap<TableName, DbTable>,
}

impl Catalog {
    /// Build a catalog from table definitions, indexed by table name.
    pub fn new(tables: impl IntoIterator<Item = DbTable>) -> Self {
        Catalog {
            tables: tables
                .into_iter()
                .map(|table| (table.name.clone(), table))
                .collect(),
        }
    }

    /// The schema of table `name`, if the catalog contains it.
    pub fn table(&self, name: &str) -> Option<&DbTable> {
        self.tables.get(name)
    }

    /// Every table, in no particular order.
    pub fn tables(&self) -> impl Iterator<Item = &DbTable> {
        self.tables.values()
    }
}

impl DbColumn {
    /// An unqualified column definition; [`DbTable::new`] fills in `table`.
    pub fn new(name: impl Into<ColumnName>, r#type: ValueType) -> Self {
        DbColumn {
            table: TableName::from(""),
            name: name.into(),
            r#type,
        }
    }
}

impl std::fmt::Display for DbTable {
    /// One line for the log: the table, its key, and every column with
    /// its type in row-layout order (the key columns first, the rest by
    /// name).
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let key: Vec<&str> = self.pkey.iter().map(ColumnName::as_str).collect();
        write!(f, "`{}` key ({}), {} columns:", self.name, key.join(", "), self.columns.len())?;
        for name in self.row_schema.names() {
            match self.columns.get(name) {
                Some(column) => write!(f, " {name} {:?}", column.r#type)?,
                None => write!(f, " {name}")?,
            }
        }
        Ok(())
    }
}

impl DbTable {
    /// The layout of this table's rows: the key columns first, the rest
    /// by name; every row decoded from the table shares it.
    pub fn row_schema(&self) -> &Arc<RowSchema> {
        &self.row_schema
    }

    /// The layout of this table's keys: the key columns, in order.
    pub fn key_schema(&self) -> &Arc<RowSchema> {
        &self.key_schema
    }

    /// Build a table, enforcing the schema invariants.
    ///
    /// # Panics
    ///
    /// On a duplicate column name, a duplicate pkey name, or a pkey name
    /// that is not in `columns` — a broken schema definition is a
    /// programming error, not a runtime condition.
    pub fn new(
        name: impl Into<TableName>,
        pkey: impl IntoIterator<Item = impl Into<ColumnName>>,
        columns: Vec<DbColumn>,
    ) -> Self {
        let name = name.into();
        let pkey: Vec<ColumnName> = pkey.into_iter().map(Into::into).collect();

        let mut by_name: HashMap<ColumnName, DbColumn> = HashMap::with_capacity(columns.len());
        for mut column in columns {
            column.table = name.clone();
            let column_name = column.name.clone();
            assert!(
                by_name.insert(column_name.clone(), column).is_none(),
                "table `{name}`: column `{column_name}` declared twice"
            );
        }
        for (index, key) in pkey.iter().enumerate() {
            assert!(
                by_name.contains_key(key),
                "table `{name}`: pkey column `{key}` is not in the column list"
            );
            assert!(
                !pkey[..index].contains(key),
                "table `{name}`: pkey column `{key}` declared twice"
            );
        }

        let mut rest: Vec<ColumnName> = by_name
            .keys()
            .filter(|column| !pkey.contains(column))
            .cloned()
            .collect();
        rest.sort_by(|a, b| a.as_str().cmp(b.as_str()));
        let row_schema = RowSchema::new(pkey.iter().cloned().chain(rest));
        let key_schema = RowSchema::new(pkey.iter().cloned());
        let put_plan = Arc::new(PutPlan::new(&name, &row_schema, &by_name));
        DbTable {
            name,
            pkey,
            columns: by_name,
            row_schema,
            key_schema,
            put_plan,
        }
    }

    /// The bytes and types the transport writes around the values of a
    /// row on [`DbTable::row_schema`].
    pub fn put_plan(&self) -> &PutPlan {
        &self.put_plan
    }

    /// The definition of column `name`, if the table declares it.
    pub fn column(&self, name: &str) -> Option<&DbColumn> {
        self.columns.get(name)
    }

    /// Is `name` one of the primary-key columns?
    pub fn is_pkey(&self, name: &str) -> bool {
        self.pkey.iter().any(|key| key == name)
    }

    /// The primary-key columns' definitions, in declaration order.
    pub fn pkey_columns(&self) -> impl Iterator<Item = &DbColumn> {
        self.pkey.iter().filter_map(|key| self.column(key.as_str()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A table's log line names its key and lists every column with its
    /// type, the key first and the rest by name.
    #[test]
    fn a_table_displays_its_key_and_typed_columns_in_layout_order() {
        let table = DbTable::new(
            "tickets",
            ["id"],
            vec![
                DbColumn::new("title", ValueType::String),
                DbColumn::new("id", ValueType::Int),
                DbColumn::new("owner", ValueType::String),
            ],
        );
        assert_eq!(
            table.to_string(),
            "`tickets` key (id), 3 columns: id Int owner String title String"
        );
    }

    /// [`DbTable::new`] stamps the table name onto every column and resolves
    /// columns and pkey membership by name.
    #[test]
    fn new_stamps_table_onto_columns_and_resolves_by_name() {
        let table = DbTable::new(
            "tickets",
            ["id"],
            vec![
                DbColumn::new("id", ValueType::Int),
                DbColumn::new("status", ValueType::String),
            ],
        );
        let status = table.column("status").expect("declared");
        assert_eq!(status.table, "tickets");
        assert_eq!(status.r#type, ValueType::String);
        assert!(table.is_pkey("id"));
        assert!(!table.is_pkey("status"));
        assert!(table.column("ghost").is_none());
    }

    /// Declaring the same column name twice panics in [`DbTable::new`].
    #[test]
    #[should_panic(expected = "declared twice")]
    fn duplicate_column_names_are_rejected() {
        DbTable::new(
            "t",
            ["a"],
            vec![
                DbColumn::new("a", ValueType::Int),
                DbColumn::new("a", ValueType::String),
            ],
        );
    }

    /// A pkey entry naming an undeclared column panics in [`DbTable::new`].
    #[test]
    #[should_panic(expected = "not in the column list")]
    fn pkey_must_reference_a_declared_column() {
        DbTable::new("t", ["ghost"], vec![DbColumn::new("a", ValueType::Int)]);
    }
}

//! Where in the source's history a write or a storage read sits: one WAL
//! location ([`Lsn`]) for both. The engine itself never compares
//! locations; the runtime does, to bring a read's result up to the point
//! the engine has reached before the engine sees it (see `sync::Runtime`).

use std::fmt;

use super::frame::{DataFrameKey, DataFrameRow};

/// A WAL location: the 64-bit form of Postgres's `X/Y`. A write carries
/// the location of its transaction's commit; a read carries the location
/// its snapshot reflects every commit up to.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Default)]
pub struct Lsn(pub u64);

impl Lsn {
    /// Parse Postgres's `X/Y` spelling (both halves hexadecimal).
    pub fn parse(text: &str) -> Option<Lsn> {
        let (high, low) = text.trim().split_once('/')?;
        let high = u64::from_str_radix(high, 16).ok()?;
        let low = u64::from_str_radix(low, 16).ok()?;
        Some(Lsn((high << 32) | low))
    }
}

impl fmt::Display for Lsn {
    /// Postgres's `X/Y` spelling.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:X}/{:X}", self.0 >> 32, self.0 & 0xFFFF_FFFF)
    }
}

/// The result of one storage read: the rows, and the location the read's
/// snapshot reflects every commit up to (and nothing beyond).
#[derive(Debug, Clone, PartialEq)]
pub struct Snapshot {
    pub rows: Vec<(DataFrameKey, DataFrameRow)>,
    pub at: Lsn,
}

#[cfg(test)]
mod tests {
    use super::*;

    /// `X/Y` parses hexadecimal halves into one ordered number and prints
    /// back the same way.
    #[test]
    fn lsn_round_trips() {
        let lsn = Lsn::parse("1/A0").unwrap();
        assert_eq!(lsn, Lsn((1 << 32) | 0xA0));
        assert_eq!(lsn.to_string(), "1/A0");
        assert!(Lsn::parse("0/FFFFFFFF").unwrap() < Lsn::parse("1/0").unwrap());
        assert!(Lsn::parse("nonsense").is_none());
    }
}

//! The join layer against a reference evaluator, over runs of random
//! writes: inner edges driven from either side, chains of them, `EXISTS`
//! inside `OR`, and pages (`ORDER BY` / `LIMIT`) that drive their own
//! inner edges, at the root and per parent row. After every write each
//! subscription's parts must show exactly what evaluating its query over
//! the storage from scratch gives: a row passes when its own `WHERE`
//! holds with every `EXISTS` answered by a passing row of that sub, a
//! page is the best rows *that pass*, and a sub's rows are shown under
//! the shown rows of its parent.

use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::rc::Rc;

use xyne_sync::ivm::{Engine, Fetch, MultiTableIVM, QueryPart, SubId, evaluate_with, order_rows};
use xyne_sync::model::*;
use xyne_sync::sync::{Local, Lsn, MemoryStorage, Runtime, Snapshot};

/// The join layer under the synchronous driver: every read is landed
/// inline.
type Ivm = Local<MultiTableIVM, MemoryStorage>;

/// A table of integer columns keyed by `id`.
fn table(name: &str, columns: &[&str]) -> DbTable {
    let mut all = vec![DbColumn::new("id", ValueType::Int)];
    all.extend(
        columns
            .iter()
            .map(|column| DbColumn::new(*column, ValueType::Int)),
    );
    DbTable::new(name, ["id"], all)
}

/// `table WHERE filter ORDER BY order, id LIMIT limit`.
fn node(name: &str, filter: Where, order: &[(&str, Order)], limit: u32) -> SingleTableReadQuery {
    let mut order_by: Vec<OrderBy> = order
        .iter()
        .map(|(column, direction)| OrderBy::new(*column, *direction))
        .collect();
    order_by.push(OrderBy::new("id", Order::ASC));
    SingleTableReadQuery {
        table: TableName::from(name),
        filter,
        order_by,
        limit,
    }
}

/// Every row of `name`.
fn all(name: &str) -> SingleTableReadQuery {
    node(name, Where::AND(Vec::new()), &[], u32::MAX)
}

/// `open = 1`.
fn open() -> Where {
    Where::condition("open", ComparisonOperator::EQ, Value::Int(1))
}

/// `spec` with its root page read whole.
fn whole(mut spec: MultiTableReadQuery) -> MultiTableReadQuery {
    spec.page = PageRead::Whole;
    spec
}

/// The subscriptions under test, by name.
fn specs() -> Vec<(&'static str, MultiTableReadQuery)> {
    let users = || MultiTableReadQuery::single(all("users"));
    let profiles = || MultiTableReadQuery::single(all("profiles"));
    let users_with_profiles = |driver: fn(MultiTableReadQuery, &str, &str) -> Join| {
        MultiTableReadQuery::new(all("users"), vec![driver(profiles(), "id", "user_id")])
    };
    let from_main = |sub, main: &str, column: &str| Join::inner_from_main(sub, main, column);
    let from_sub = |sub, main: &str, column: &str| Join::inner(sub, main, column);
    vec![
        (
            "inner from the main",
            MultiTableReadQuery::new(
                node("tickets", open(), &[], u32::MAX),
                vec![Join::inner_from_main(users(), "assignee", "id")],
            ),
        ),
        (
            "a chain from the main",
            MultiTableReadQuery::new(
                node("tickets", open(), &[], u32::MAX),
                vec![Join::inner_from_main(
                    users_with_profiles(from_main),
                    "assignee",
                    "id",
                )],
            ),
        ),
        (
            "a gated driver",
            MultiTableReadQuery::new(
                node("tickets", open(), &[], u32::MAX),
                vec![Join::inner(
                    users_with_profiles(from_main),
                    "assignee",
                    "id",
                )],
            ),
        ),
        (
            "a chain from the subs",
            MultiTableReadQuery::new(
                node("tickets", open(), &[], u32::MAX),
                vec![Join::inner(users_with_profiles(from_sub), "assignee", "id")],
            ),
        ),
        (
            "a page under a gate",
            MultiTableReadQuery::new(
                node("tickets", open(), &[], 3),
                vec![Join::inner_from_main(users(), "assignee", "id")],
            ),
        ),
        (
            "a page under a chain",
            MultiTableReadQuery::new(
                node("tickets", open(), &[("project", Order::DESC)], 3),
                vec![Join::inner_from_main(
                    users_with_profiles(from_main),
                    "assignee",
                    "id",
                )],
            ),
        ),
        (
            "a page under a gate, read whole",
            whole(MultiTableReadQuery::new(
                node("tickets", open(), &[], 3),
                vec![Join::inner_from_main(users(), "assignee", "id")],
            )),
        ),
        (
            "a page under a chain, read whole",
            whole(MultiTableReadQuery::new(
                node("tickets", open(), &[("project", Order::DESC)], 3),
                vec![Join::inner_from_main(
                    users_with_profiles(from_main),
                    "assignee",
                    "id",
                )],
            )),
        ),
        (
            "a page under a gate inside OR",
            MultiTableReadQuery::new(
                node(
                    "tickets",
                    Where::AND(vec![
                        open(),
                        Where::OR(vec![
                            Where::condition("project", ComparisonOperator::EQ, Value::Int(0)),
                            Where::exists("assignee", 0),
                        ]),
                    ]),
                    &[("project", Order::ASC)],
                    4,
                ),
                vec![Join::inner_from_main(users(), "assignee", "id")],
            ),
        ),
        (
            "a page under a gate and a restriction",
            MultiTableReadQuery::new(
                node("tickets", open(), &[], 2),
                vec![
                    Join::inner_from_main(users(), "assignee", "id"),
                    Join::inner(
                        MultiTableReadQuery::single(node(
                            "teams",
                            Where::condition("active", ComparisonOperator::EQ, Value::Int(1)),
                            &[],
                            u32::MAX,
                        )),
                        "team",
                        "id",
                    ),
                ],
            ),
        ),
        (
            "a page per parent under a gate",
            MultiTableReadQuery::new(
                node("teams", Where::AND(Vec::new()), &[], u32::MAX),
                vec![Join::left(
                    MultiTableReadQuery::new(
                        node("tickets", open(), &[("project", Order::DESC)], 2),
                        vec![Join::inner_from_main(users(), "assignee", "id")],
                    ),
                    "id",
                    "team",
                )],
            ),
        ),
        (
            "a page per parent under a gate below a paged root",
            MultiTableReadQuery::new(
                node(
                    "teams",
                    Where::AND(Vec::new()),
                    &[("active", Order::DESC)],
                    2,
                ),
                vec![Join::left(
                    MultiTableReadQuery::new(
                        node("tickets", open(), &[("project", Order::DESC)], 2),
                        vec![Join::inner_from_main(users(), "assignee", "id")],
                    ),
                    "id",
                    "team",
                )],
            ),
        ),
    ]
}

/// A row's value in `column`.
fn value_of(row: &DataFrameRow, column: &ColumnName) -> Value {
    row.data
        .get(column.as_str())
        .cloned()
        .unwrap_or(Value::Null)
}

/// A row's `id`.
fn id_of(key: &DataFrameKey) -> i64 {
    match key.pkey_value["id"] {
        Value::Int(id) => id,
        _ => panic!("an integer key"),
    }
}

/// The rows of `spec`'s node that pass: their own `WHERE` with every
/// `EXISTS` leaf answered by a passing row of the inner sub it names, and
/// the inner subs no leaf names conjoined.
fn passing(
    spec: &MultiTableReadQuery,
    storage: &MemoryStorage,
) -> Vec<(DataFrameKey, DataFrameRow)> {
    let inner: Vec<(&Join, Vec<Value>)> = spec
        .joins
        .iter()
        .filter(|join| join.is_inner)
        .map(|join| {
            let values = passing(&join.sub, storage)
                .iter()
                .map(|(_, row)| value_of(row, &join.sub_table_column))
                .collect();
            (join, values)
        })
        .collect();
    let named: Vec<bool> = inner
        .iter()
        .enumerate()
        .map(|(index, (join, _))| {
            spec.main_table.filter.contains(&Condition::new(
                join.main_table_column.clone(),
                ComparisonOperator::EXISTS,
                Value::Int(index as i64),
            ))
        })
        .collect();
    storage
        .rows(&all(spec.main_table.table.as_str()))
        .into_iter()
        .filter(|(_, row)| {
            let exists = |leaf: &Condition| -> bool {
                let Value::Int(index) = leaf.value else {
                    return false;
                };
                inner.get(index as usize).is_some_and(|(join, values)| {
                    let value = value_of(row, &join.main_table_column);
                    !value.is_null() && values.contains(&value)
                })
            };
            evaluate_with(&spec.main_table.filter, &row.data, &mut 0, &exists)
                && inner.iter().zip(&named).all(|((join, values), named)| {
                    *named || values.contains(&value_of(row, &join.main_table_column))
                })
        })
        .collect()
}

/// The best `limit` of `rows` under `order`.
fn page(
    mut rows: Vec<(DataFrameKey, DataFrameRow)>,
    query: &SingleTableReadQuery,
) -> Vec<(DataFrameKey, DataFrameRow)> {
    rows.sort_by(|(_, a), (_, b)| order_rows(&query.order_by, a, b));
    if query.limit != u32::MAX {
        rows.truncate(query.limit as usize);
    }
    rows
}

/// What every part of `spec` shows, by part: the root's page of passing
/// rows, and under each shown row the passing rows of each sub carrying
/// its join value, a sub with a limit paged per parent value.
fn expected(
    spec: &MultiTableReadQuery,
    storage: &MemoryStorage,
) -> BTreeMap<Vec<usize>, BTreeSet<i64>> {
    let mut out = BTreeMap::new();
    let root = page(passing(spec, storage), &spec.main_table);
    descend(spec, &root, Vec::new(), storage, &mut out);
    out
}

/// Record `shown` for the node at `path` and evaluate the subs under it.
fn descend(
    spec: &MultiTableReadQuery,
    shown: &[(DataFrameKey, DataFrameRow)],
    path: Vec<usize>,
    storage: &MemoryStorage,
    out: &mut BTreeMap<Vec<usize>, BTreeSet<i64>>,
) {
    out.insert(
        path.clone(),
        shown.iter().map(|(key, _)| id_of(key)).collect(),
    );
    for (index, join) in spec.joins.iter().enumerate() {
        let candidates = passing(&join.sub, storage);
        let mut values: Vec<Value> = shown
            .iter()
            .map(|(_, row)| value_of(row, &join.main_table_column))
            .filter(|value| !value.is_null())
            .collect();
        values.sort_by(xyne_sync::ivm::order_cmp);
        values.dedup();
        let mut under = Vec::new();
        for value in values {
            let of_value: Vec<(DataFrameKey, DataFrameRow)> = candidates
                .iter()
                .filter(|(_, row)| value_of(row, &join.sub_table_column) == value)
                .cloned()
                .collect();
            under.extend(page(of_value, &join.sub.main_table));
        }
        let mut child = path.clone();
        child.push(index);
        descend(&join.sub, &under, child, storage, out);
    }
}

/// What the engine shows for every part of `spec`.
fn actual(
    ivm: &MultiTableIVM,
    sub: SubId,
    spec: &MultiTableReadQuery,
    path: Vec<usize>,
    out: &mut BTreeMap<Vec<usize>, BTreeSet<i64>>,
) {
    let part = QueryPart::try_new(&path).expect("a shallow tree");
    let rows = ivm.rows_for(sub, part).unwrap_or_default();
    out.insert(path.clone(), rows.keys().map(id_of).collect());
    for (index, join) in spec.joins.iter().enumerate() {
        let mut child = path.clone();
        child.push(index);
        actual(ivm, sub, &join.sub, child, out);
    }
}

/// A small deterministic generator.
struct Random(u64);

impl Random {
    /// The next value below `bound`.
    fn below(&mut self, bound: u64) -> i64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        (self.0 % bound) as i64
    }
}

/// One random write over the four tables, mirrored into `present` (which
/// ids exist per table) so inserts, updates and deletes stay valid.
fn random_write(
    random: &mut Random,
    present: &mut HashMap<&'static str, BTreeSet<i64>>,
) -> WriteQuery {
    let (name, ids, columns): (&'static str, u64, Vec<(&str, u64)>) = match random.below(10) {
        0..=4 => (
            "tickets",
            14,
            vec![("open", 2), ("assignee", 5), ("project", 4), ("team", 3)],
        ),
        5..=6 => ("users", 5, vec![("rank", 3)]),
        7..=8 => ("profiles", 6, vec![("user_id", 5)]),
        _ => ("teams", 3, vec![("active", 2)]),
    };
    let id = random.below(ids);
    let key = DataFrameKey::new([("id", Value::Int(id))]);
    let exists = present.entry(name).or_default().contains(&id);
    if exists && random.below(3) == 0 {
        present.entry(name).or_default().remove(&id);
        return WriteQuery::DELETE(DeleteQuery {
            table: TableName::from(name),
            pkey_value: key,
        });
    }
    let mut data: HashMap<ColumnName, Value> = columns
        .iter()
        .map(|(column, bound)| ((*column).into(), Value::Int(random.below(*bound))))
        .collect();
    data.insert("id".into(), Value::Int(id));
    let record = DataFrameRow::from(data);
    if exists {
        WriteQuery::UPDATE(UpdateQuery {
            table: TableName::from(name),
            pkey_value: key,
            record,
        })
    } else {
        present.entry(name).or_default().insert(id);
        WriteQuery::INSERT(InsertQuery {
            table: TableName::from(name),
            pkey_value: key,
            record,
        })
    }
}

/// Run `steps` random writes from `seed`, some before the subscriptions
/// register and the rest after, checking every subscription against the
/// reference after each. `GATED_TRACE=<step>` prints, for the seed
/// `GATED_SEED` names (1 by default), every write from that step on with
/// what it produced and the trees' state.
fn run(seed: u64, steps: usize) {
    let _ = (
        table("tickets", &["open", "assignee", "project", "team"]),
        table("users", &["rank"]),
        table("profiles", &["user_id"]),
        table("teams", &["active"]),
    );
    let storage = Rc::new(MemoryStorage::new());
    let mut ivm: Ivm = Local::new(MultiTableIVM::new(), storage.clone());
    let mut random = Random(seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1);
    let mut present: HashMap<&'static str, BTreeSet<i64>> = HashMap::new();
    for _ in 0..40 {
        storage.apply(&random_write(&mut random, &mut present));
    }
    let registered: Vec<(&str, MultiTableReadQuery, SubId)> = specs()
        .into_iter()
        .map(|(name, spec)| {
            let (sub, _) = ivm.register_query(spec.clone());
            (name, spec, sub)
        })
        .collect();
    for step in 0..=steps {
        for (name, spec, sub) in &registered {
            let mut shown = BTreeMap::new();
            actual(ivm.engine(), *sub, spec, Vec::new(), &mut shown);
            assert_eq!(
                shown,
                expected(spec, &storage),
                "`{name}`, seed {seed}, after {step} writes: {:#?}",
                ivm.engine().describe(*sub)
            );
            assert!(
                ivm.engine().hydrated(*sub),
                "`{name}` has a read out, seed {seed}, after {step} writes"
            );
        }
        let write = random_write(&mut random, &mut present);
        storage.apply(&write);
        let traced_seed: u64 = std::env::var("GATED_SEED")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(1);
        let trace = std::env::var("GATED_TRACE")
            .ok()
            .and_then(|v| v.parse::<usize>().ok())
            .is_some_and(|from| seed == traced_seed && step >= from);
        if trace {
            eprintln!("--- write {step}: {write:?}");
        }
        let out = ivm.incremental_update(&write);
        if trace {
            for delta in &out {
                eprintln!("    {delta:?}");
            }
            let stats = ivm.engine().stats();
            eprintln!(
                "    stats: reads {} lookups {} rounds {} rejected {}",
                stats.storage_reads, stats.page_lookups, stats.page_rounds, stats.window_rejections
            );
            for (name, _, sub) in &registered {
                for line in ivm.engine().describe(*sub) {
                    eprintln!("    `{name}` {line}");
                }
            }
        }
        let problems = ivm.engine().audit();
        assert!(
            problems.is_empty(),
            "seed {seed}, write {step} ({write:?}): {problems:#?}"
        );
    }
}

#[test]
fn every_shape_shows_what_the_reference_evaluates() {
    for seed in 1..=40 {
        run(seed, 250);
    }
}

/// The same runs with the reads landing late: every read is answered
/// from the storage as it was when it was asked for and landed some
/// writes later, in a random order, the way a slow database would; the
/// runtime brings each result up to the engine's position. Whenever
/// nothing is out the subscriptions must show what the reference
/// evaluates, and the counts must agree with the rows.
fn run_late(seed: u64, steps: usize) {
    let storage = MemoryStorage::new();
    let mut runtime = Runtime::new(MultiTableIVM::new());
    let mut random = Random(seed.wrapping_mul(0xD6E8_FEB8_6659_FD93) | 1);
    let mut present: HashMap<&'static str, BTreeSet<i64>> = HashMap::new();
    let mut lsn = 0u64;
    for _ in 0..40 {
        storage.apply(&random_write(&mut random, &mut present));
        lsn += 1;
    }
    runtime.progress(Lsn(lsn));
    let mut out: Vec<(Fetch, Snapshot)> = Vec::new();
    let asked = |selects: Vec<Fetch>,
                 storage: &MemoryStorage,
                 lsn: u64,
                 out: &mut Vec<(Fetch, Snapshot)>| {
        for fetch in selects {
            let snapshot = Snapshot {
                rows: storage.rows(&fetch.query),
                at: Lsn(lsn),
            };
            out.push((fetch, snapshot));
        }
    };
    let only: Option<usize> = std::env::var("GATED_ONLY")
        .ok()
        .and_then(|v| v.parse().ok());
    let mut registered: Vec<(&str, MultiTableReadQuery, SubId)> = Vec::new();
    for (index, (name, spec)) in specs().into_iter().enumerate() {
        if only.is_some_and(|only| only != index) {
            continue;
        }
        let (sub, step) = runtime.register(spec.clone());
        asked(step.selects, &storage, lsn, &mut out);
        registered.push((name, spec, sub));
    }
    let trace_from: Option<usize> = std::env::var("GATED_TRACE")
        .ok()
        .and_then(|v| v.parse().ok())
        .filter(|_| std::env::var("GATED_SEED").is_ok());
    for step in 0..steps {
        let trace = trace_from.is_some_and(|from| step >= from);
        let land = !out.is_empty() && (random.below(3) != 0 || step + 1 == steps);
        if land {
            let (fetch, snapshot) = out.remove(random.below(out.len() as u64) as usize);
            if trace {
                eprintln!(
                    "--- step {step}: land {:?} {:?} for {:?}: {} rows {:?}",
                    fetch.id,
                    fetch.kind,
                    fetch.sub,
                    snapshot.rows.len(),
                    fetch.query.filter
                );
            }
            let landed = runtime.fetched(fetch.id, snapshot);
            asked(landed.selects, &storage, lsn, &mut out);
        } else {
            let write = random_write(&mut random, &mut present);
            storage.apply(&write);
            lsn += 1;
            if trace {
                eprintln!("--- step {step}: write {write:?}");
            }
            let routed = runtime.write(&write, Lsn(lsn));
            asked(routed.selects, &storage, lsn, &mut out);
        }
        if trace {
            for (name, _, sub) in &registered {
                for line in runtime.engine().describe(*sub) {
                    eprintln!("    `{name}` {line}");
                }
            }
        }
        let problems = runtime.engine().audit();
        assert!(
            problems.is_empty(),
            "seed {seed}, step {step}: {problems:#?}"
        );
        if !out.is_empty() {
            continue;
        }
        for (name, spec, sub) in &registered {
            let mut shown = BTreeMap::new();
            actual(runtime.engine(), *sub, spec, Vec::new(), &mut shown);
            assert_eq!(
                shown,
                expected(spec, &storage),
                "`{name}`, seed {seed}, quiet after step {step}: {:#?}",
                runtime.engine().describe(*sub)
            );
        }
    }
    let mut rounds = 0;
    while !out.is_empty() {
        let (fetch, snapshot) = out.remove(0);
        if trace_from.is_some() {
            eprintln!(
                "--- drain {rounds}: land {:?} {:?} for {:?}: {} rows {:?}",
                fetch.id,
                fetch.kind,
                fetch.sub,
                snapshot.rows.len(),
                fetch.query.filter
            );
        }
        let landed = runtime.fetched(fetch.id, snapshot);
        asked(landed.selects, &storage, lsn, &mut out);
        if trace_from.is_some() {
            for (name, _, sub) in &registered {
                for line in runtime.engine().describe(*sub) {
                    eprintln!("    `{name}` {line}");
                }
            }
        }
        rounds += 1;
        assert!(rounds < 10_000, "seed {seed}: the reads never settle");
    }
    for (name, spec, sub) in &registered {
        let mut shown = BTreeMap::new();
        actual(runtime.engine(), *sub, spec, Vec::new(), &mut shown);
        assert_eq!(
            shown,
            expected(spec, &storage),
            "`{name}`, seed {seed}, at the end"
        );
        assert!(runtime.engine().hydrated(*sub), "`{name}`, seed {seed}");
    }
}

#[test]
fn every_shape_converges_with_reads_landing_late() {
    let seeds: Vec<u64> = match std::env::var("GATED_SEED")
        .ok()
        .and_then(|v| v.parse().ok())
    {
        Some(seed) => vec![seed],
        None => (1..=40).collect(),
    };
    for seed in seeds {
        run_late(seed, 400);
    }
}

//! What the asynchronous driver promises its consumer, over an in-memory
//! store: a subscription is named before anything is said about it, a
//! registration served from a tree the engine already holds needs no
//! storage read and still reports itself complete, and one committed
//! transaction reaches the consumer as one event carrying every delta of
//! it whatever else is happening. These are the properties the client side
//! builds its pokes on; each was a live defect before it was pinned here.

use std::collections::HashMap;
use std::rc::Rc;
use std::time::Duration;

use tokio::sync::mpsc;
use tokio::task::{LocalSet, spawn_local};
use xyne_sync::ivm::MultiTableIVM;
use xyne_sync::model::*;
use xyne_sync::sync::{
    Command, Event, Lsn, MemoryStorage, Service, Storage, StorageError, SubId, Transaction,
};

/// Run `body` on a current-thread runtime with a local task set (the
/// driver and its storage are single-threaded).
fn block_on<F: std::future::Future>(body: F) -> F::Output {
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("tokio runtime");
    LocalSet::new().block_on(&runtime, body)
}

/// The primary key of `id`.
fn pkey(id: i64) -> HashMap<ColumnName, Value> {
    HashMap::from([("id".into(), Value::Int(id))])
}

/// One full ticket row: every column the table declares.
fn ticket(id: i64, status: &str) -> DataFrameRow {
    DataFrameRow::from(HashMap::from([
        ("id".into(), Value::Int(id)),
        ("status".into(), Value::String(status.to_owned())),
    ]))
}

/// An insert of `ticket(id, status)`.
fn insert(id: i64, status: &str) -> WriteQuery {
    WriteQuery::INSERT(InsertQuery {
        table: TableName::from("tickets"),
        pkey_value: DataFrameKey::new(pkey(id)),
        record: ticket(id, status),
    })
}

/// The one query these scenarios subscribe to: the open tickets.
fn open_tickets() -> MultiTableReadQuery {
    MultiTableReadQuery::single(SingleTableReadQuery::new(
        "tickets",
        Where::condition("status", ComparisonOperator::EQ, "OPEN"),
        OrderBy::new("id", Order::ASC),
        u32::MAX,
    ))
}

/// A driver over `storage`, with the events it sends and the commands it
/// takes; the driver runs as a task of the caller's local set.
fn start(
    storage: Rc<MemoryStorage>,
) -> (
    mpsc::Sender<Command<MultiTableReadQuery>>,
    mpsc::UnboundedReceiver<Event>,
) {
    let (events_tx, events) = mpsc::unbounded_channel();
    let (service, commands) = Service::new(MultiTableIVM::new(), storage, events_tx);
    spawn_local(service.run());
    (commands, events)
}

/// Every event the driver sends within a short window, in order.
async fn drain(events: &mut mpsc::UnboundedReceiver<Event>) -> Vec<Event> {
    let mut seen = Vec::new();
    while let Ok(Some(event)) =
        tokio::time::timeout(Duration::from_millis(200), events.recv()).await
    {
        seen.push(event);
    }
    seen
}

/// The names of the events, for readable assertions.
fn shapes(events: &[Event]) -> Vec<&'static str> {
    events
        .iter()
        .map(|event| match event {
            Event::Registered { .. } => "registered",
            Event::Hydrated(_) => "hydrated",
            Event::Landed { .. } => "landed",
            Event::Refused { .. } => "refused",
            Event::Committed { .. } => "committed",
            Event::Capped { .. } => "capped",
            Event::Heavy { .. } => "heavy",
        })
        .collect()
}

/// The deltas an event carries.
fn updates_of(event: &Event) -> &[xyne_sync::ivm::Delta] {
    match event {
        Event::Registered { updates, .. }
        | Event::Landed { updates }
        | Event::Committed { updates, .. } => updates,
        Event::Hydrated(_) | Event::Refused { .. } | Event::Capped { .. } | Event::Heavy { .. } => {
            &[]
        }
    }
}

/// The rows added by every event, as ids.
fn ids(events: &[Event]) -> Vec<i64> {
    let mut out = Vec::new();
    for event in events {
        for update in updates_of(event) {
            if let DataFrameOperation::Add(key, _) = &update.op
                && let Some(Value::Int(id)) = key.pkey_value.get(&ColumnName::from("id"))
            {
                out.push(*id);
            }
        }
    }
    out.sort_unstable();
    out
}

/// The subscription a registration became, and the token it answers.
fn registered(events: &[Event]) -> Option<(u64, SubId)> {
    events.iter().find_map(|event| match event {
        Event::Registered { token, sub, .. } => Some((*token, *sub)),
        _ => None,
    })
}

/// A registration is announced before anything is said about it: the
/// first event is the subscription's id, carrying the token the command
/// was sent with, and only then do its rows and its completion follow.
/// Without that order a consumer meets a `SubId` it cannot place and
/// drops the rows and the completion on the floor.
#[test]
fn a_registration_is_named_before_its_rows() {
    block_on(async {
        let storage = Rc::new(MemoryStorage::new());
        storage.apply(&insert(1, "OPEN"));
        storage.apply(&insert(2, "DONE"));
        let (commands, mut events) = start(storage);

        commands
            .send(Command::Register {
                sink: 0,
                query: open_tickets(),
                token: 7,
            })
            .await
            .expect("send");
        let seen = drain(&mut events).await;

        assert_eq!(
            shapes(&seen).first(),
            Some(&"registered"),
            "the subscription is named first, got {:?}",
            shapes(&seen)
        );
        let (token, sub) = registered(&seen).expect("the registration is answered");
        assert_eq!(token, 7, "the token comes back unchanged");
        assert_eq!(ids(&seen), vec![1], "only the open ticket is delivered");
        assert!(
            seen.iter().any(|event| matches!(
                event,
                Event::Hydrated(subs) if subs.contains(&sub)
            )),
            "the subscription reports itself complete, got {:?}",
            shapes(&seen)
        );
    });
}

/// A second subscription to a query the engine already holds is served
/// from that tree: it is named, given its rows and reported complete
/// without a storage read, so a consumer that waits for a landing before
/// telling the client would wait for something that never comes.
#[test]
fn a_twin_registration_completes_without_a_read() {
    block_on(async {
        let storage = Rc::new(MemoryStorage::new());
        storage.apply(&insert(1, "OPEN"));
        let (commands, mut events) = start(storage);

        commands
            .send(Command::Register {
                sink: 0,
                query: open_tickets(),
                token: 1,
            })
            .await
            .expect("send");
        let first = drain(&mut events).await;
        assert!(
            first
                .iter()
                .any(|event| matches!(event, Event::Landed { .. })),
            "the first registration reads storage, got {:?}",
            shapes(&first)
        );

        commands
            .send(Command::Register {
                sink: 0,
                query: open_tickets(),
                token: 2,
            })
            .await
            .expect("send");
        let twin = drain(&mut events).await;

        let (token, sub) = registered(&twin).expect("the twin is answered");
        assert_eq!(token, 2, "the twin's own token comes back");
        assert_eq!(ids(&twin), vec![1], "the twin is given the held row");
        assert!(
            twin.iter().any(|event| matches!(
                event,
                Event::Hydrated(subs) if subs.contains(&sub)
            )),
            "the twin reports itself complete, got {:?}",
            shapes(&twin)
        );
        assert!(
            !twin
                .iter()
                .any(|event| matches!(event, Event::Landed { .. })),
            "the twin needs no storage read, got {:?}",
            shapes(&twin)
        );
    });
}

/// One committed transaction reaches the consumer as one event carrying
/// every delta of it: the driver routes every write of a commit in a
/// single synchronous step, so nothing a client is told can be cut in the
/// middle of a commit, and the rows of that commit travel together with
/// its position.
#[test]
fn a_commit_arrives_as_one_batch() {
    block_on(async {
        let storage = Rc::new(MemoryStorage::new());
        let (commands, mut events) = start(storage);

        commands
            .send(Command::Register {
                sink: 0,
                query: open_tickets(),
                token: 1,
            })
            .await
            .expect("send");
        drain(&mut events).await;

        commands
            .send(Command::Transaction(Transaction::new(
                vec![insert(10, "OPEN"), insert(11, "OPEN"), insert(12, "DONE")],
                Lsn(100),
            )))
            .await
            .expect("send");
        let seen = drain(&mut events).await;

        assert_eq!(
            seen.iter()
                .filter(|event| !updates_of(event).is_empty())
                .count(),
            1,
            "the commit's rows travel in one event, got {:?}",
            shapes(&seen)
        );
        assert!(
            matches!(seen.last(), Some(Event::Committed { updates, .. }) if updates.len() == 2),
            "and that event is the commit itself, got {:?}",
            shapes(&seen)
        );
        assert_eq!(
            ids(&seen),
            vec![10, 11],
            "both open tickets of the commit are delivered together"
        );
    });
}

/// A committed transaction reports where the engine now is (the feed's
/// progress mark) and carries the watched writes it held, which is what a
/// consumer batching per transaction flushes on.
#[test]
fn a_commit_reports_the_position_and_the_watched_writes() {
    block_on(async {
        let storage = Rc::new(MemoryStorage::new());
        let (commands, mut events) = start(storage);

        commands
            .send(Command::Transaction(Transaction {
                writes: vec![insert(1, "OPEN")],
                at: Lsn(42),
                progress: Lsn(50),
                watched: vec![insert(1, "OPEN")],
                schema: Vec::new(),
                catalog: None,
                received: std::time::Instant::now(),
                committed_at_micros: 0,
                decode: std::time::Duration::ZERO,
            }))
            .await
            .expect("send");
        let seen = drain(&mut events).await;

        let committed = seen.iter().find_map(|event| match event {
            Event::Committed {
                position, watched, ..
            } => Some((*position, watched.len())),
            _ => None,
        });
        assert_eq!(
            committed,
            Some((Lsn(50), 1)),
            "the progress mark and the watched write are reported, got {:?}",
            shapes(&seen)
        );
        assert!(
            matches!(seen.as_slice(), [Event::Committed { updates, .. }] if updates.is_empty()),
            "the commit is the one event; nobody subscribed, so it carries no delta, got {:?}",
            shapes(&seen)
        );
    });
}

/// Storage that refuses every read, the way a read past the row budget is.
struct Refusing(MemoryStorage);

impl Storage for Refusing {
    /// Refused, whatever is asked.
    async fn select(&self, query: &SingleTableReadQuery) -> Result<Snapshot, StorageError> {
        Err(StorageError::refused(format!(
            "a read on `{}` returned more than 1 rows",
            query.table
        )))
    }

    /// [`MemoryStorage::advance`].
    fn advance(&self, feed: Lsn) {
        self.0.advance(feed)
    }

    /// [`MemoryStorage::floor`].
    fn floor(&self) -> Lsn {
        self.0.floor()
    }

    /// [`MemoryStorage::absorb`].
    fn absorb(&self, write: &WriteQuery, at: Lsn) {
        self.0.absorb(write, at)
    }
}

/// A refused read is not parked and retried: the subscription that was
/// waiting on it is unregistered, its client is told why, and it is never
/// reported complete.
#[test]
fn a_refused_read_unregisters_the_subscription_and_says_why() {
    block_on(async {
        let storage = Rc::new(Refusing(MemoryStorage::new()));
        let (events_tx, mut events) = mpsc::unbounded_channel();
        let (service, commands) = Service::new(MultiTableIVM::new(), storage, events_tx);
        spawn_local(service.run());
        commands
            .send(Command::Register {
                sink: 0,
                query: open_tickets(),
                token: 3,
            })
            .await
            .expect("send");
        let seen = drain(&mut events).await;
        let (_, sub) = registered(&seen).expect("the registration is named first");
        assert_eq!(
            shapes(&seen),
            vec!["registered", "refused"],
            "named, then refused, and never hydrated"
        );
        assert!(
            seen.iter().any(|event| matches!(
                event,
                Event::Refused { sub: refused, reason } if *refused == sub && reason.contains("tickets")
            )),
            "the refusal names the subscription and the table, got {seen:?}"
        );
    });
}

/// Storage whose reads wait until the gate opens, so a read can be in
/// flight while another registration arrives.
struct Gated {
    inner: MemoryStorage,
    open: Rc<std::cell::Cell<bool>>,
}

impl Storage for Gated {
    /// The inner read, once the gate is open.
    async fn select(&self, query: &SingleTableReadQuery) -> Result<Snapshot, StorageError> {
        while !self.open.get() {
            tokio::time::sleep(Duration::from_millis(5)).await;
        }
        self.inner.select(query).await
    }

    /// [`MemoryStorage::advance`].
    fn advance(&self, feed: Lsn) {
        self.inner.advance(feed)
    }

    /// [`MemoryStorage::floor`].
    fn floor(&self) -> Lsn {
        self.inner.floor()
    }

    /// [`MemoryStorage::absorb`].
    fn absorb(&self, write: &WriteQuery, at: Lsn) {
        self.inner.absorb(write, at)
    }
}

/// A twin that registers while the first subscription's read is still
/// out joins that read, and both are reported complete when it lands:
/// the landing names every subscription waiting on it, not only the one
/// that asked.
#[test]
fn a_twin_joining_a_read_in_flight_completes_when_it_lands() {
    block_on(async {
        let inner = MemoryStorage::new();
        inner.apply(&insert(1, "OPEN"));
        let open = Rc::new(std::cell::Cell::new(false));
        let storage = Rc::new(Gated {
            inner,
            open: open.clone(),
        });
        let (events_tx, mut events) = mpsc::unbounded_channel();
        let (service, commands) = Service::new(MultiTableIVM::new(), storage, events_tx);
        spawn_local(service.run());
        for token in [1u64, 2] {
            commands
                .send(Command::Register {
                    sink: 0,
                    query: open_tickets(),
                    token,
                })
                .await
                .expect("send");
        }
        let before = drain(&mut events).await;
        assert_eq!(
            shapes(&before),
            vec!["registered", "registered"],
            "both are named and neither is complete while the read is out"
        );
        let subs: Vec<SubId> = before
            .iter()
            .filter_map(|event| match event {
                Event::Registered { sub, .. } => Some(*sub),
                _ => None,
            })
            .collect();
        open.set(true);
        let after = drain(&mut events).await;
        let hydrated: Vec<SubId> = after
            .iter()
            .flat_map(|event| match event {
                Event::Hydrated(subs) => subs.clone(),
                _ => Vec::new(),
            })
            .collect();
        assert!(
            subs.iter().all(|sub| hydrated.contains(sub)),
            "both subscriptions complete on the one landing, got {:?} for {subs:?}",
            shapes(&after)
        );
        assert!(
            ids(&after).contains(&1),
            "the row lands, got {:?}",
            ids(&after)
        );
    });
}

/// Two consumers, one tree: subscriptions of one query registered from two
/// sinks share the engine's tree, and each sink hears of its own alone.
/// A registration is answered to the sink that asked; a write's delta
/// reaches both, each copy naming only that sink's subscriptions (three
/// of them on the first sink, as one shared list); a subscription let go
/// hears nothing more; and a group of subscriptions released together
/// leaves its sink silent while the other still hears.
#[test]
fn deltas_reach_the_sink_that_owns_each_subscription() {
    block_on(async {
        let storage = Rc::new(MemoryStorage::new());
        storage.apply(&insert(1, "OPEN"));
        let (first_tx, mut first) = mpsc::unbounded_channel();
        let (second_tx, mut second) = mpsc::unbounded_channel();
        let (service, commands) =
            Service::new(MultiTableIVM::new(), storage.clone(), first_tx.clone());
        spawn_local(service.with_sinks(vec![first_tx, second_tx]).run());

        let mut owned: Vec<Vec<SubId>> = vec![Vec::new(), Vec::new()];
        for (token, sink) in [(1u64, 0usize), (2, 0), (3, 0), (4, 1)] {
            commands
                .send(Command::Register {
                    sink,
                    query: open_tickets(),
                    token,
                })
                .await
                .expect("send");
            let (mine, other) = if sink == 0 {
                (&mut first, &mut second)
            } else {
                (&mut second, &mut first)
            };
            let seen = drain(mine).await;
            let (answered, sub) = registered(&seen).expect("answered to the sink that asked");
            assert_eq!(answered, token);
            assert_eq!(ids(&seen), vec![1], "with its row");
            assert!(
                registered(&drain(other).await).is_none(),
                "the other sink hears nothing of it"
            );
            owned[sink].push(sub);
        }

        storage.apply(&insert(2, "OPEN"));
        commands
            .send(Command::Transaction(Transaction::new(
                vec![insert(2, "OPEN")],
                Lsn(1),
            )))
            .await
            .expect("send");
        for (sink, events) in [(0usize, &mut first), (1, &mut second)] {
            let seen = drain(events).await;
            let deltas: Vec<_> = seen.iter().flat_map(updates_of).collect();
            assert_eq!(deltas.len(), 1, "one delta for the one row, sink {sink}");
            let mut named: Vec<SubId> = deltas[0].targets().map(|target| target.sub).collect();
            named.sort();
            assert_eq!(named, owned[sink], "naming that sink's subscriptions alone");
        }

        commands
            .send(Command::UnregisterAll(owned[0].clone()))
            .await
            .expect("send");
        storage.apply(&insert(3, "OPEN"));
        commands
            .send(Command::Transaction(Transaction::new(
                vec![insert(3, "OPEN")],
                Lsn(2),
            )))
            .await
            .expect("send");
        let quiet = drain(&mut first).await;
        assert!(
            quiet.iter().flat_map(updates_of).next().is_none(),
            "the released sink has nothing left to hear"
        );
        let heard = drain(&mut second).await;
        assert_eq!(ids(&heard), vec![3], "the other still hears");
    });
}

/// A read that comes back with at least half the row limit is told, once,
/// to the owner of a subscription waiting on it, with the table and the
/// row count, so the transport can name the query; a small read is not.
#[test]
fn a_heavy_read_is_told_to_the_subscriptions_owner() {
    block_on(async {
        let storage = Rc::new(MemoryStorage::new());
        for id in 1..=6 {
            storage.apply(&insert(id, "OPEN"));
        }
        storage.apply(&insert(7, "DONE"));
        let stats = xyne_sync::stats::Stats::shared();
        stats
            .read_row_limit
            .store(10, std::sync::atomic::Ordering::Relaxed);
        let (events_tx, mut events) = mpsc::unbounded_channel();
        let (service, commands) = Service::new(MultiTableIVM::new(), storage, events_tx);
        spawn_local(service.with_stats(stats.clone()).run());

        commands
            .send(Command::Register {
                sink: 0,
                query: open_tickets(),
                token: 1,
            })
            .await
            .expect("send");
        let seen = drain(&mut events).await;
        let (_, sub) = registered(&seen).expect("registered");
        let heavy: Vec<_> = seen
            .iter()
            .filter_map(|event| match event {
                Event::Heavy { sub, table, rows } => Some((*sub, table.as_str().to_owned(), *rows)),
                _ => None,
            })
            .collect();
        assert_eq!(
            heavy,
            vec![(sub, "tickets".to_owned(), 6)],
            "{:?}",
            shapes(&seen)
        );

        let done = MultiTableReadQuery::single(SingleTableReadQuery::new(
            "tickets",
            Where::condition("status", ComparisonOperator::EQ, "DONE"),
            OrderBy::new("id", Order::ASC),
            u32::MAX,
        ));
        commands
            .send(Command::Register {
                sink: 0,
                query: done,
                token: 2,
            })
            .await
            .expect("send");
        let seen = drain(&mut events).await;
        assert!(
            !shapes(&seen).contains(&"heavy"),
            "one row of a limit of ten is no heavy read, got {:?}",
            shapes(&seen)
        );
    });
}

/// A feed that reopens its slot is sent again the transactions the server
/// had not seen confirmed. The driver applies each transaction once: one
/// that committed at or below where the engine already is goes by
/// without a second event, a position mark is a step with nothing in it,
/// and the transactions after the repeat are applied as ever.
#[test]
fn a_transaction_the_feed_repeats_is_applied_once() {
    block_on(async {
        let storage = Rc::new(MemoryStorage::new());
        let (events_tx, mut events) = mpsc::unbounded_channel();
        let (feed, transactions) = mpsc::channel(16);
        let (service, commands) = Service::new(MultiTableIVM::new(), storage, events_tx);
        spawn_local(service.with_feed(transactions).run());
        commands
            .send(Command::Register {
                sink: 0,
                query: open_tickets(),
                token: 1,
            })
            .await
            .expect("send");
        drain(&mut events).await;

        let committed = |id: i64, at: u64| {
            let mut transaction = Transaction::new(vec![insert(id, "OPEN")], Lsn(at));
            transaction.committed_at_micros = 1;
            transaction
        };
        assert!(Transaction::mark(Lsn(5)).is_mark());
        assert!(!committed(1, 10).is_mark());
        assert!(committed(1, 10).repeats(Lsn(10)));
        assert!(!committed(1, 10).repeats(Lsn(9)));
        assert!(!Transaction::mark(Lsn(5)).repeats(Lsn(10)));

        feed.send(committed(1, 10)).await.expect("feed");
        feed.send(committed(2, 20)).await.expect("feed");
        feed.send(Transaction::mark(Lsn(25))).await.expect("feed");
        feed.send(committed(2, 20)).await.expect("feed");
        feed.send(committed(1, 10)).await.expect("feed");
        feed.send(committed(3, 30)).await.expect("feed");
        let seen = drain(&mut events).await;
        assert_eq!(
            shapes(&seen),
            vec!["committed", "committed", "committed", "committed"],
            "two transactions, the mark, and the one after the repeats"
        );
        assert_eq!(ids(&seen), vec![1, 2, 3], "each row added once");
        let positions: Vec<Lsn> = seen
            .iter()
            .filter_map(|event| match event {
                Event::Committed { position, .. } => Some(*position),
                _ => None,
            })
            .collect();
        assert_eq!(positions, vec![Lsn(10), Lsn(20), Lsn(25), Lsn(30)]);
    });
}

/// With several consumers, a commit wakes only those with something to
/// hear once they are serving: the first commit reaches every consumer (it
/// is the one they start serving on), a later one with deltas for one
/// consumer reaches that one alone, and a watched write reaches them all.
#[test]
fn a_serving_consumer_is_not_woken_for_nothing() {
    block_on(async {
        let storage = Rc::new(MemoryStorage::new());
        let (owner_tx, mut owner) = mpsc::unbounded_channel();
        let (other_tx, mut other) = mpsc::unbounded_channel();
        let (service, commands) =
            Service::new(MultiTableIVM::new(), storage, owner_tx.clone());
        let service = service.with_sinks(vec![owner_tx, other_tx]);
        spawn_local(service.run());

        let transaction = |id: i64, at: u64, watched: bool| {
            let write = insert(id, "OPEN");
            Transaction {
                watched: if watched { vec![write.clone()] } else { Vec::new() },
                writes: vec![write],
                at: Lsn(at),
                progress: Lsn(at),
                schema: Vec::new(),
                catalog: None,
                received: std::time::Instant::now(),
                committed_at_micros: 0,
                decode: Duration::ZERO,
            }
        };

        commands
            .send(Command::Transaction(transaction(1, 10, false)))
            .await
            .expect("send");
        let (first_owner, first_other) = (drain(&mut owner).await, drain(&mut other).await);
        assert_eq!(shapes(&first_owner), vec!["committed"]);
        assert_eq!(shapes(&first_other), vec!["committed"], "every consumer starts serving");

        commands
            .send(Command::Register {
                sink: 0,
                query: open_tickets(),
                token: 1,
            })
            .await
            .expect("send");
        drain(&mut owner).await;
        commands
            .send(Command::Transaction(transaction(2, 20, false)))
            .await
            .expect("send");
        let (owner_seen, other_seen) = (drain(&mut owner).await, drain(&mut other).await);
        assert_eq!(shapes(&owner_seen), vec!["committed"]);
        assert_eq!(ids(&owner_seen), vec![2]);
        assert!(other_seen.is_empty(), "nothing for it: {:?}", shapes(&other_seen));

        commands
            .send(Command::Transaction(transaction(3, 30, true)))
            .await
            .expect("send");
        let other_seen = drain(&mut other).await;
        assert!(
            matches!(other_seen.as_slice(), [Event::Committed { updates, watched, .. }]
                if updates.is_empty() && watched.len() == 1),
            "a watched write reaches every consumer: {:?}",
            shapes(&other_seen)
        );
        assert_eq!(ids(&drain(&mut owner).await), vec![3]);
    });
}

//! The engine's cost on production-shaped trees, the storage's time taken
//! out: the support desk's ticket list as the dashboard registers it (ten
//! windows over one channel, each a page read in batches under an
//! `EXISTS` gate), writes on that gate's table, single-row writes into an
//! engine holding large trees, and every channel of a workspace
//! registered again by a client whose tree is already held. Each prints
//! the engine's time and the storage's, the reads and the rows read.
//! Ignored by default (they take seconds in release and minutes in
//! debug); run with
//! `cargo test --release --test engine_cost -- --ignored --nocapture`.

macro_rules! row {
    ($($column:expr => $value:expr),* $(,)?) => {
        &[$(($column, ::xyne_sync::model::Value::from($value))),*][..]
    };
}

#[path = "xyne_spaces_queries/catalog.rs"]
#[allow(dead_code)]
mod catalog;
#[path = "xyne_spaces_queries/zql.rs"]
#[allow(dead_code)]
mod zql;

use std::cell::Cell;
use std::collections::HashMap;
use std::rc::Rc;
use std::time::{Duration, Instant};

use xyne_sync::client::plan::{Planner, Policy, Side};
use xyne_sync::ivm::MultiTableIVM;
use xyne_sync::model::Order::DESC;
use xyne_sync::model::{
    ColumnName, DataFrameKey, DataFrameRow, InsertQuery, Lsn, MultiTableReadQuery,
    SingleTableReadQuery, Snapshot, Value, WriteQuery,
};
use xyne_sync::sync::{Local, MemoryStorage, Storage, StorageError};
use zql::{Q, eq, is_null, or, zql};

const ME: &str = "u-me";
const WS: &str = "ws-1";

/// In-memory storage that adds up the time its reads take.
struct Timed {
    inner: MemoryStorage,
    spent: Cell<Duration>,
    reads: Cell<u64>,
    rows: Cell<u64>,
}

impl Timed {
    /// An empty store with its counters at zero.
    fn new() -> Self {
        Timed {
            inner: MemoryStorage::new(),
            spent: Cell::new(Duration::ZERO),
            reads: Cell::new(0),
            rows: Cell::new(0),
        }
    }
    /// The time, reads and rows since the last call, and a fresh start.
    fn take(&self) -> (Duration, u64, u64) {
        let out = (self.spent.get(), self.reads.get(), self.rows.get());
        self.spent.set(Duration::ZERO);
        self.reads.set(0);
        self.rows.set(0);
        out
    }
}

impl Storage for Timed {
    async fn select(&self, query: &SingleTableReadQuery) -> Result<Snapshot, StorageError> {
        let started = Instant::now();
        let out = self.inner.select(query).await;
        self.spent.set(self.spent.get() + started.elapsed());
        self.reads.set(self.reads.get() + 1);
        if let Ok(snapshot) = &out {
            self.rows.set(self.rows.get() + snapshot.rows.len() as u64);
        }
        out
    }
    async fn count(&self, query: &MultiTableReadQuery, cap: u64) -> Result<u64, StorageError> {
        self.inner.count(query, cap).await
    }
    fn advance(&self, feed: Lsn) {
        self.inner.advance(feed)
    }
    fn floor(&self) -> Lsn {
        self.inner.floor()
    }
    fn absorb(&self, write: &WriteQuery, at: Lsn) {
        self.inner.absorb(write, at)
    }
}

/// A full image of `table` from `pairs`, as the fixtures build one.
fn image(table: &str, pairs: &[(&str, Value)]) -> WriteQuery {
    let data: HashMap<ColumnName, Value> = catalog::columns(table)
        .iter()
        .map(|(column, _)| {
            let value = pairs
                .iter()
                .find(|(name, _)| name == column)
                .map(|(_, v)| v.clone())
                .unwrap_or_else(|| {
                    if *column == "workspaceId" {
                        Value::from(WS)
                    } else {
                        Value::Null
                    }
                });
            (ColumnName::from(*column), value)
        })
        .collect();
    let key = DataFrameKey::new([(catalog::pkey(table), data[catalog::pkey(table)].clone())]);
    WriteQuery::INSERT(InsertQuery {
        table: table.into(),
        pkey_value: key,
        record: DataFrameRow::from(data),
    })
}

/// The tree planned on `counts` (table, narrowed) -> rows, production's policy.
fn planned(q: &Q, counts: &dyn Fn(&str, bool) -> u64) -> MultiTableReadQuery {
    let (spec, _) = q.clone().eq("workspaceId", WS).build();
    let mut planner = Planner::new(
        spec,
        Policy {
            limit: 100_000,
            preferred: Side::Parent,
            whole: 5_000,
        },
    );
    let asked: Vec<(usize, bool)> = planner
        .counts()
        .iter()
        .map(|c| (c.node, c.narrowed))
        .collect();
    for (node, narrowed) in asked {
        let rows = counts(planner.table_of(node), narrowed);
        planner.answer(node, narrowed, rows);
    }
    planner.decide().expect("planned")
}

/// The engine under the synchronous driver over timed storage, and a
/// clock for the writes.
struct Bench {
    ivm: Local<MultiTableIVM, Timed>,
    storage: Rc<Timed>,
    clock: u64,
}

impl Bench {
    /// An empty engine over empty storage.
    fn new() -> Self {
        let storage = Rc::new(Timed::new());
        Bench {
            ivm: Local::new(MultiTableIVM::new(), storage.clone()),
            storage,
            clock: 0,
        }
    }
    /// Put a row into storage without routing it.
    fn seed(&self, table: &str, pairs: &[(&str, Value)]) {
        self.storage.inner.apply(&image(table, pairs));
    }
    /// Register `query`, printing engine time (total minus storage) and storage stats.
    fn register(&mut self, label: &str, query: MultiTableReadQuery) -> xyne_sync::model::SubId {
        self.storage.take();
        let started = Instant::now();
        let (sub, updates) = self.ivm.register_query(query);
        let total = started.elapsed();
        let (io, reads, rows) = self.storage.take();
        eprintln!(
            "{label:<44} engine {:>8.1} ms  storage {:>7.1} ms  {:>5} reads {:>7} rows read {:>7} updates",
            (total - io).as_secs_f64() * 1000.0,
            io.as_secs_f64() * 1000.0,
            reads,
            rows,
            updates.len()
        );
        sub
    }
    /// Route `writes`, printing the engine's time per write.
    fn write_all(&mut self, label: &str, writes: Vec<WriteQuery>) {
        self.storage.take();
        let n = writes.len();
        let started = Instant::now();
        let mut updates = 0;
        for write in &writes {
            self.clock += 1;
            self.storage.inner.apply(write);
            updates += self.ivm.incremental_update(write).len();
        }
        let total = started.elapsed();
        let (io, reads, rows) = self.storage.take();
        eprintln!(
            "{label:<44} engine {:>8.1} ms  storage {:>7.1} ms  {:>5} reads {:>7} rows read {:>7} updates  ({:.1} µs engine per write)",
            (total - io).as_secs_f64() * 1000.0,
            io.as_secs_f64() * 1000.0,
            reads,
            rows,
            updates,
            (total - io).as_secs_f64() * 1e6 / n as f64
        );
    }
}

/// The desk list's query at `limit`, as karun.raj's list registers it.
fn desk_page(limit: u32) -> Q {
    zql("tickets")
        .eq("channelId", "c-desk")
        .eq("isArchived", false)
        .where_exists("channel", |ch| {
            ch.eq("id", "c-desk")
                .eq("workspaceId", WS)
                .where_exists("participants", |p| {
                    p.eq("userId", ME).eq("channelId", "c-desk")
                })
        })
        .where_exists("formEntityValues", |f| {
            f.eq("entityType", "TICKET").eq("fieldId", "F1")
        })
        .order_by("lastEmailAt", DESC)
        .order_by("id", DESC)
        .limit(limit)
        .related("emailDrafts", |d| {
            d.filter(or(vec![eq("userId", ME), is_null("userId")]))
        })
        .related("emailReads", |r| r.eq("userId", ME))
        .related("userMailbox", |m| m.eq("userId", ME))
        .related("formEntityValues", |f| {
            f.eq("entityType", "TICKET").in_("fieldId", &["F1"])
        })
}

/// The desk channel at production size: `tickets` tickets, a form value
/// of the filtered field on all but one in 94 (27 836 of that field in
/// the workspace), two other fields on each, and the caller's reads,
/// mailbox rows and drafts.
fn seed_desk(b: &Bench, tickets: usize) {
    b.seed(
        "channels",
        row!["id" => "c-desk", "visibility" => "PRIVATE"],
    );
    b.seed(
        "channel_participants",
        row!["id" => "p-me", "channelId" => "c-desk", "userId" => ME],
    );
    let mut fev = 0;
    for i in 0..tickets {
        let id = format!("t{i}");
        let conv = format!("cv{i}");
        b.seed("tickets", row!["id" => id.as_str(), "channelId" => "c-desk", "isArchived" => false, "lastEmailAt" => 1_000_000 + (i as i64 * 7919) % 100_000, "conversationId" => conv.as_str()]);
        if i % 94 != 0 {
            b.seed("form_entity_values", row!["id" => format!("f1-{i}").as_str(), "entityId" => id.as_str(), "entityType" => "TICKET", "fieldId" => "F1", "actualFieldValue" => "\"x\""]);
            fev += 1;
        }
        for f in ["F2", "F3"] {
            b.seed("form_entity_values", row!["id" => format!("{f}-{i}").as_str(), "entityId" => id.as_str(), "entityType" => "TICKET", "fieldId" => f, "actualFieldValue" => "\"y\""]);
        }
        if i % 2 == 0 {
            b.seed(
                "email_reads",
                row!["id" => format!("r{i}").as_str(), "ticketId" => id.as_str(), "userId" => ME],
            );
        }
        if i % 3 == 0 {
            b.seed("ticket_user_mailbox", row!["id" => format!("m{i}").as_str(), "ticketId" => id.as_str(), "userId" => ME, "state" => "INBOX"]);
        }
        if i % 50 == 0 {
            b.seed("email_drafts", row!["id" => format!("d{i}").as_str(), "conversationId" => conv.as_str(), "userId" => ME]);
        }
    }
    let mut j = 0;
    while fev < 27_836 {
        b.seed("form_entity_values", row!["id" => format!("fo-{j}").as_str(), "entityId" => format!("other{j}").as_str(), "entityType" => "TICKET", "fieldId" => "F1", "actualFieldValue" => "\"x\""]);
        fev += 1;
        j += 1;
    }
}

/// A: the desk list's ten windows, planned as production plans them.
#[test]
#[ignore]
fn a_desk_windows() {
    let mut b = Bench::new();
    seed_desk(&b, 8508);
    let counts = |table: &str, narrowed: bool| match (table, narrowed) {
        ("tickets", false) => 8508,
        ("tickets", true) => 8418,
        ("form_entity_values", _) => 27_836,
        _ => 1,
    };
    let mut limit = 51;
    while limit <= 13_056 {
        b.register(
            &format!("A desk window limit {limit}"),
            planned(&desk_page(limit), &counts),
        );
        limit *= 2;
    }
}

